a84b4498fa41b0da6f44c6abe1f27c13e9064aadc2de774fb7ff99d74",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/blood-death-knight-tank-pve-rotation-cooldowns-abilities",["sha256"]="66c8faca4451af43f22cdfb23e8ebfff3cb9ec7761a4185901796734b3ebff7b",["date"]="2026-10-19"}},["rotationDiagram"]={["kind"]="priority",["heading"]="Opening Single Target Rotation",["steps"]={{["spellID"]=49576,["name"]="Death Grip",["icon"]="Interface\\Icons\\Spell_DeathKnight_Strangulate",["condition"]="Death Grip taunts the boss, allowing you a 3-second window to establish snap threat. Do not use this rotationally but as a Taunt or means to move a mob in the encounter."},{["spellID"]=49909,["name"]="Icy Touch",["icon"]="Interface\\Icons\\Spell_DeathKnight_IceTouch",["condition"]="Icy Touch;"},{["spellID"]=49921,["name"]="Plague Strike",["icon"]="Interface\\Icons\\Spell_DeathKnight_EmpowerRuneBlade",["condition"]="Plague Strike;"},{["spellID"]=49924,["name"]="Death Strike",["icon"]="Interface\\Icons\\Spell_DeathKnight_Butcher2",["condition"]="Death Strike;"},{["spellID"]=49930,["name"]="Blood Strike",["icon"]="Interface\\Icons\\Spell_Deathknight_DeathStrike",["condition"]="Blood Strike;"},{["spellID"]=45529,["name"]="Blood Tap",["icon"]="Interface\\Icons\\Spell_DeathKnight_BloodTap",["condition"]="Blood Tap should be spent on an Icy Touch for early snap threat;"},{["spellID"]=49930,["name"]="Blood Strike",["icon"]="Interface\\Icons\\Spell_Deathknight_DeathStrike",["condition"]="Blood Strike;"},{["spellID"]=49909,["name"]="Icy Touch",["icon"]="Interface\\Icons\\Spell_DeathKnight_IceTouch",["condition"]="Icy Touch;"},{["spellID"]=47568,["name"]="Empower Rune Weapon",["icon"]="Interface\\Icons\\INV_Sword_62",["condition"]="Empower Rune Weapon;"},{["spellID"]=50842,["name"]="Pestilence",["icon"]="Interface\\Icons\\Spell_Shadow_PlagueCloud",["condition"]="Pestilence to refresh your diseases;"},{["spellID"]=49924,["name"]="Death Strike",["icon"]="Interface\\Icons\\Spell_DeathKnight_Butcher2",["condition"]="Death Strike to spend your Unholy Runes;"},{["spellID"]=49909,["name"]="Icy Touch",["icon"]="Interface\\Icons\\Spell_DeathKnight_IceTouch",["condition"]="Spam Icy Touch with your remaining Runes."}}}}},["DEATHKNIGHT:Frost"]={["classToken"]="DEATHKNIGHT",["sourceSpec"]="Frost",["role"]="melee",["pve"]={["overview"]={["ruRU"]={"Боец ближнего боя с уроном льдом и физическими атаками.","Сильный урон по одной цели и нескольким близким противникам; личная защита.","Зависимость от рун и времени у цели; ограниченная мобильность."},["enUS"]={"Death Knight is capable of both Tanking or DPSing and are near the best at both depending on the encounter. Frost is primarily a DPS specialization with a large emphasis on procs and a constantly changing order of priorities that will keep you on your","Some of the strongest single-target and sustained cleave damage in the game. Ability to talent for powerful group buffs increasing your groups damage. Powerful personal defensive cooldowns. Death Grip allows for repositioning mobs and other players in a way that","Extremely immobile and vulnerable to slows/stuns after cooldowns are expended. Must be in melee range to be able to self-sustain. Heavily dependant on generation of Runic Power."}},["rotation"]={["ruRU"]="Поддерживайте обе болезни. Уничтожение — основной расход рун; обновляйте болезни мором только с соответствующим символом. Ледяной удар расходует силу рун; воющий ветер по одной цели — с проком инея.",["enUS"]="If you have not already, please read the Spell Summary page. Knowing how each spell and ability works in detail will greatly increase your understanding of the topics discussed on this page. Frost Death Knights are one of the strongest melee DPS in the entire game. The amazing buffs that they bring to any group and the utility they have with powerful abilities such as Death Grip, along with the massive amount of damage they can do, puts them in contention for being the among the best DPS melee class. This guide assumes you are using the talent build that can be found on our talents page and are playing a max-level character. If you are looking for leveling-based help please refer to leveling page for a leveling-specific rotation, or our Pre-Patch guide for advice at Level 70. Frost Death"},["builds"]={{["key"]="pve_0",["title"]="Talent Build (15/56/0)",["talentsString"]="23050005-32005350352203012300033101351-",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=1939,["rank"]=2,["spellID"]=49483,["tree"]=1,["minLevel"]=10,["maxRank"]=2,["name"]="Butchery",["nameRu"]="Butchery"},{["talentID"]=1945,["rank"]=3,["spellID"]=49491,["tree"]=1,["minLevel"]=10,["maxRank"]=3,["name"]="Subversion",["nameRu"]="Subversion"},{["talentID"]=1938,["rank"]=5,["spellID"]=49393,["tree"]=1,["minLevel"]=15,["maxRank"]=5,["name"]="Bladed Armor",["nameRu"]="Bladed Armor"},{["talentID"]=1943,["rank"]=5,["spellID"]=49480,["tree"]=1,["minLevel"]=20,["maxRank"]=5,["name"]="Dark Conviction",["nameRu"]="Dark Conviction"},{["talentID"]=2031,["rank"]=3,["spellID"]=51456,["tree"]=2,["minLevel"]=10,["maxRank"]=3,["name"]="Improved Icy Touch",["nameRu"]="Improved Icy Touch"},{["talentID"]=2020,["rank"]=2,["spellID"]=50147,["tree"]=2,["minLevel"]=10,["maxRank"]=2,["name"]="Runic Power Mastery",["nameRu"]="Runic Power Mastery"},{["talentID"]=1973,["rank"]=5,["spellID"]=49664,["tree"]=2,["minLevel"]=15,["maxRank"]=5,["name"]="Black Ice",["nameRu"]="Black Ice"},{["talentID"]=2022,["rank"]=3,["spellID"]=50138,["tree"]=2,["minLevel"]=15,["maxRank"]=3,["name"]="Nerves of Cold Steel",["nameRu"]="Nerves of Cold Steel"},{["talentID"]=2042,["rank"]=5,["spellID"]=50887,["tree"]=2,["minLevel"]=20,["maxRank"]=5,["name"]="Icy Talons",["nameRu"]="Icy Talons"},{["talentID"]=2048,["rank"]=3,["spellID"]=51473,["tree"]=2,["minLevel"]=20,["maxRank"]=3,["name"]="Annihilation",["nameRu"]="Annihilation"},{["talentID"]=2044,["rank"]=5,["spellID"]=51130,["tree"]=2,["minLevel"]=25,["maxRank"]=5,["nam