f8897752e7b352355e4e86a1e1",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/frost-death-knight-dps-pve-rotation-cooldowns-abilities",["sha256"]="7721c68fefdb0aaf1fa2bed2fb7e386e0209e536062ce667848daf5c3419d109",["date"]="2026-10-19"}},["rotationDiagram"]={["kind"]="priority",["heading"]="Single-Target DPS",["steps"]={{["spellID"]=49909,["name"]="Icy Touch",["icon"]="Interface\\Icons\\Spell_DeathKnight_IceTouch",["condition"]="Icy Touch;"},{["spellID"]=49921,["name"]="Plague Strike",["icon"]="Interface\\Icons\\Spell_DeathKnight_EmpowerRuneBlade",["condition"]="Plague Strike;"},{["spellID"]=51271,["name"]="Unbreakable Armor",["icon"]="Interface\\Icons\\INV_Armor_Helm_Plate_Naxxramas_RaidWarrior_C_01",["condition"]="Unbreakable Armor/Blood Tap;"},{["spellID"]=51425,["name"]="Obliterate",["icon"]="Interface\\Icons\\Spell_Deathknight_ClassIcon",["condition"]="Obliterate;"},{["spellID"]=50842,["name"]="Pestilence",["icon"]="Interface\\Icons\\Spell_Shadow_PlagueCloud",["condition"]="Pestilence;"},{["spellID"]=47568,["name"]="Empower Rune Weapon",["icon"]="Interface\\Icons\\INV_Sword_62",["condition"]="Empower Rune Weapon;"},{["spellID"]=51425,["name"]="Obliterate",["icon"]="Interface\\Icons\\Spell_Deathknight_ClassIcon",["condition"]="Obliterate three times."}}}}},["DEATHKNIGHT:Unholy"]={["classToken"]="DEATHKNIGHT",["sourceSpec"]="Unholy",["role"]="melee",["pve"]={["overview"]={["ruRU"]={"Боец ближнего боя с болезнями и усиленными прислужниками.","Поддержка группы, урон болезнями и прислужниками, защитные инструменты.","Питомец требует контроля; замедления и перемещения мешают нанесению урона."},["enUS"]={"Death Knight is capable of both Tanking or DPSing and are near the best at both depending on the encounter. Unholy is primarily a DPS specialization with a large emphasis on diseases and pets, but if you are looking for a more reactive/proc-based style of","Commands two powerful minions that are greatly empowered by talents. Ability to talent for powerful debuffs, greatly increasing your group's damage. Powerful personal and group defensive cooldowns. Death Grip allows for repositioning mobs and other players in a way that","Extremely immobile and vulnerable to slows or stuns after cooldowns are expended. Must be in melee range to be able to self-sustain. Pets can at times be vulnerable to raid-wide damage mechanics. Heavily dependant on generation of Runic Power."}},["rotation"]={["ruRU"]="Поддерживайте обе болезни и активность вурдалака. Расходуйте руны согласно выбранному варианту, силу рун — ликом смерти. Призыв горгульи согласуйте с усилениями; варианты с лужей и ударом плети не смешивайте.",["enUS"]="If you have not already, please read the Spell Summary page. Knowing how each spell and ability works in detail will greatly increase your understanding of the topics discussed on this page. Unholy Death Knights are one of the strongest melee DPS in the entire game. The amazing buffs that they bring to any group and the utility they have with powerful abilities such as Death Grip, along with the massive amount of damage they can do, puts them in contention for being the among the best DPS melee class. Unholy operates similar to the other two Death Knight specs in that your focus is more of a priority system than a true rotation. However, it is much more of a set rotation than the other two specs due to a lack of damage-increasing procs resulting in a more steady"},["builds"]={{["key"]="pve_0",["title"]="Talent Build (0/19/52)",["talentsString"]="-320043500002-2300303050032152000150013133051",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=2031,["rank"]=3,["spellID"]=51456,["tree"]=2,["minLevel"]=10,["maxRank"]=3,["name"]="Improved Icy Touch",["nameRu"]="Improved Icy Touch"},{["talentID"]=2020,["rank"]=2,["spellID"]=50147,["tree"]=2,["minLevel"]=10,["maxRank"]=2,["name"]="Runic Power Mastery",["nameRu"]="Runic Power Mastery"},{["talentID"]=1973,["rank"]=4,["spellID"]=49663,["tree"]=2,["min