pellID"]=49921,["name"]="Plague Strike",["icon"]="Interface\\Icons\\Spell_DeathKnight_EmpowerRuneBlade",["condition"]="Plague Strike;"},{["spellID"]=49909,["name"]="Icy Touch",["icon"]="Interface\\Icons\\Spell_DeathKnight_IceTouch",["condition"]="Icy Touch;"},{["spellID"]=49930,["name"]="Blood Strike",["icon"]="Interface\\Icons\\Spell_Deathknight_DeathStrike",["condition"]="Blood Strike twice;"},{["spellID"]=45529,["name"]="Blood Tap",["icon"]="Interface\\Icons\\Spell_DeathKnight_BloodTap",["condition"]="Blood Tap;"},{["spellID"]=49938,["name"]="Death and Decay",["icon"]="Interface\\Icons\\Spell_Shadow_DeathAndDecay",["condition"]="Death and Decay;"},{["spellID"]=63560,["name"]="Ghoul Frenzy",["icon"]="Interface\\Icons\\Ability_GhoulFrenzy",["condition"]="Ghoul Frenzy;"},{["spellID"]=49206,["name"]="Summon Gargoyle",["icon"]="Interface\\Icons\\Ability_Hunter_Pet_Bat",["condition"]="Summon Gargoyle;"},{["spellID"]=47568,["name"]="Empower Rune Weapon",["icon"]="Interface\\Icons\\INV_Sword_62",["condition"]="Empower Rune Weapon and cancel Blood Tap (you want the Blood Runes);"},{["spellID"]=42650,["name"]="Army of the Dead",["icon"]="Interface\\Icons\\Spell_DeathKnight_ArmyOfTheDead",["condition"]="Army of the Dead;"},{["spellID"]=48266,["name"]="Blood Presence",["icon"]="Interface\\Icons\\Spell_Deathknight_BloodPresence",["condition"]="Blood Presence;"}}}},["pvp"]={["overview"]={["ruRU"]={"Боец ближнего боя с давлением болезнями и прислужниками.","Высокое постоянное давление, взрывные окна и широкий набор защиты.","Оглушения и ограниченная мобильность."},["enUS"]={"Unholy Death Knight is one of the most dominant melee specs in all of PvP. Outside of their vulnerability to being stunned, Unholy Death Knight has some of the highest burst and consistent damage in the game and a cooldown to deal with almost any","",""}},["rotation"]={["ruRU"]="Удерживайте контакт с целью цепями льда и хваткой смерти; заранее используйте антимагическую защиту против контроля. Болезни и питомец создают давление, а защитные способности нужно беречь под ответ противника.",["enUS"]="As an Unholy Death Knight in PvP there is no real set rotation you should be focusing on. The usage of your damaging abilities depends on many factors but the most important thing as an Unholy Death Knight is to stay on your target as much as you possibly can. As a Death Knight your mobility will be quite limited, but if you take advantage of Anti-Magic Shell to try and preemptively avoid magic-based roots and crowd control, and make use of both Chains of Ice and Death Grip to lessen the effectiveness of your enemies' move speed bonuses, you can stick to a target quite well. Plague Strike and Icy Touch are your two main ways to apply diseases. It is crucial to keep track of your debuffs as there are many ways for other players to dispel your"},["builds"]={{["key"]="pvp_0",["title"]="Talent Build (0/18/53)",["talentsString"]="-320050510002-2301223350002150230101213103151",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=2031,["rank"]=3,["spellID"]=51456,["tree"]=2,["minLevel"]=10,["maxRank"]=3,["name"]="Improved Icy Touch",["nameRu"]="Improved Icy Touch"},{["talentID"]=2020,["rank"]=2,["spellID"]=50147,["tree"]=2,["minLevel"]=10,["maxRank"]=2,["name"]="Runic Power Mastery",["nameRu"]="Runic Power Mastery"},{["talentID"]=1973,["rank"]=5,["spellID"]=49664,["tree"]=2,["minLevel"]=15,["maxRank"]=5,["name"]="Black Ice",["nameRu"]="Black Ice"},{["talentID"]=2042,["rank"]=5,["spellID"]=50887,["tree"]=2,["minLevel"]=20,["maxRank"]=5,["name"]="Icy Talons",["nameRu"]="Icy Talons"},{["talentID"]=2215,["rank"]=1,["spellID"]=49039,["tree"]=2,["minLevel"]=20,["maxRank"]=1,["name"]="Lichborne",["nameRu"]="Lichborne"},{["talentID"]=1971,["rank"]=2,["spellID"]=49657,["tree"]=2,["minLevel"]=25,["maxRank"]=2,["name"]="Endless Winter",["nameRu"]="Endless Winter"},{["talentID"]=2082,["rank"]=2,["spellID"]=51746,["tree"]=3,["minLevel"]=10,["maxRank"]=2,["name"]="Vicious Strikes",["na