ameRu"]="Glyph of Unburdened Rebirth"}},["glyphIssues"]={},["trees"]={"Balance","Feral Combat","Restoration"},["source"]="https://www.icy-veins.com/wotlk-classic/balance-druid-dps-pve-spec-builds-talents-glyphs",["calculator"]="https://www.icy-veins.com/wotlk-classic/druid-talent-calculator#tc-000003378aaa6cbbb6fffhiii6lolqqllWWYYYYY...[[l99999mmmggjjjdd44q5551rdn|0r1F3i4m5t2e"}},["sources"]={{["url"]="https://www.icy-veins.com/wotlk-classic/balance-druid-dps-pve-guide",["sha256"]="50ed564f682c8da96423f96607ae06f680722bcda9d25c15b3ff646806a3dee4",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/balance-druid-dps-pve-spec-builds-talents-glyphs",["sha256"]="e54fa5449f57b759b6e22367fedff4776c493c7e29a52e66361bb29e50e552b9",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/balance-druid-dps-pve-rotation-cooldowns-abilities",["sha256"]="da73fa9a8f33afe4295e634f29cf39daf2e376dc0ac72a83f540201c9b4efbfa",["date"]="2026-10-19"}},["rotationDiagram"]={["kind"]="priority",["heading"]="Short Fight Single-Target Rotation for Balance Druids",["steps"]={{["spellID"]=770,["name"]="Faerie Fire",["icon"]="Interface\\Icons\\Spell_Nature_FaerieFire",["condition"]="Keep Faerie Fire on the target if raiding, for the Improved Faerie Fire debuff. You can skip it if another Druid is keeping it up and your raid has the 3% Spell Hit debuff already;"},{["spellID"]=33831,["name"]="Force of Nature",["icon"]="Interface\\Icons\\Ability_Druid_ForceofNature",["condition"]="Use Force of Nature within melee range of the boss. You can delay it to line up with Bloodlust if it won't cost you an extra use during the fight;"},{["spellID"]=48505,["name"]="Starfall",["icon"]="Interface\\Icons\\Ability_Druid_Starfall",["condition"]="Use Starfall in a position where you will not pull unwanted enemies;"},{["spellID"]=5570,["name"]="Insect Swarm",["icon"]="Interface\\Icons\\Spell_Nature_InsectSwarm",["condition"]="Apply and refresh (after it expires) Insect Swarm on the target unless currently buffed by (Lunar) Eclipse;"},{["spellID"]=48464,["name"]="Starfire",["icon"]="Interface\\Icons\\Spell_Arcane_StarFire",["condition"]="During Eclipse buffs, spam the buffed spell (Lunar = Starfire, trinkets,  Potion of Speed, and  Hyperspeed Accelerators, Solar = Wrath);"},{["spellID"]=26984,["name"]="Wrath",["icon"]="Interface\\Icons\\Spell_Nature_AbolishMagic",["condition"]="When not in an Eclipse, work towards your next one by casting either Wrath (for your first Eclipse) or Starfire, with the spell you want to cast always being the same as the buffed spell of the Eclipse you mostly recently left;"},{["spellID"]=9834,["name"]="Moonfire",["icon"]="Interface\\Icons\\Spell_Nature_StarFall",["condition"]="Moonfire if movement is needed."}}}},["pvp"]={["overview"]={["ruRU"]={"Заклинатель с резким открытием из скрытности и контролем.","Звёздопад, силы природы и периодический урон создают окно давления.","Контроль останавливает звёздопад; опасны срывы чтения."},["enUS"]={"Balance Druids have extreme burst damage during cooldowns, and can open from stealth, but also require a lot of hard-casting for damage and are easy to shut down, as Starfall stops working while the Druid is crowd controlled.","",""}},["rotation"]={["ruRU"]="Согласуйте контроль противников перед звёздопадом и силами природы. Сохраняйте возможность снять контроль в своё окно урона; между окнами используйте периодические эффекты и безопасные чтения.",["enUS"]="As a Balance Druid, you will look to start with strong burst from stealth, quickly using Starfall and Force of Nature to burst enemies down along with your damage-over-time effects and any hard-casts you can pull off. As Starfall stops working while you are crowd controlled, it is very important to have your Medallion of the Horde at hand to stop any crowd control during Starfall, and also to coordinate CC on the enemy team in order to limit their own CC potential. If enemies turn the pressure on you, you can kite away from them with Travel Form and Nature's Grasp, endure the pressure with Dire Bear Form and Frenzied Regeneration, or use Barkskin, but remember to always keep at least some pressure with your instant-cast damage-over-time effects."},["builds"]={{["key"]="pvp_0",["title"]="Balance Druid PvP Talent Build (57/0/14)",["talentsString"]="5022203125331003213035311231--230033012",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=762,["rank"]=5,["spellID"]=16818,["tree"]=1,["minLevel"]=10,["maxRank"]=5,["name"]="Starlight Wrath",["nameRu"]="Starlight Wrath"},{["talentID"]=783,["rank"]=2,["spellID"]=16846,["tree"]=1,["minLevel"]=15,["maxRank"]=3,["name"]="Moonglow",["nameRu"]="Moonglow"},{["talentID"]=1822,["rank"]=2,["spellID"]=35364,["tree"]=1,["minLevel"]=15,["maxRank"]=2,["name"]="Nature's Majesty",["nameRu"]="Nature's Majesty"},{["talentID"]=763,["rank"]=2,["spellID"]=16822,["tree"]=1,["minLevel"]=15,["maxRank"]=2,["name"]="Improved Moonfire",["nameRu"]="Improved Moonfire"},{["talentID"]=789,["rank"]=3,["spellID"]=61346,["tree"]=1,["minLevel"]=20,["maxRank"]=3,["name"]="Nature's Grace",["nameRu"]="Nature's Grace"},{["talentID"]=2240,["rank"]=1,["spellID"]=57865,["tree"]=1,["minLevel"]=20,["maxRank"]=1,["name"]="Nature's Splendor",["nameRu"]="Nature's Splendor"},{["talentID"]=764,["rank"]=2,["spellID"]=16820,["tree"]=1,["minLevel"]=20,["maxRank"]=2,["name"]="Nature's Reach",["nameRu"]="Nature's Reach"},{["talentID"]=792,["rank"]=5,["spellID"]=16913,["tree"]=1,["minLevel"]=25,["maxRank"]=5,["name"]="Vengeance",["nameRu"]="Vengeance"},{["talentID"]=784,["rank"]=3,["spellID"]=16924,["tree"]=1,["minLevel"]=25,["maxRank"]=3,["name"]="Celestial Focus",["nameRu"]="Celestial Focus"},{["talentID"]=1782,["rank"]=3,["spellID"]=33591,["tree"]=1,["minLevel"]=30,["maxRank"]=3,["name"]="Lunar Guidance",["nameRu"]="Lunar Guidance"},{["talentID"]=788,["rank"]=1,["spellID"]=5570,["tree"]=1,["minLevel"]=30,["maxRank"]=1,["name"]="Insect Swarm",["nameRu"]="Insect Swarm"},{["talen