43334,["spellID"]=57858,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorDruid",["classToken"]="DRUID",["minLevel"]=28,["name"]="Glyph of Challenging Roar",["nameRu"]="Glyph of Challenging Roar"},{["itemID"]=43335,["spellID"]=57855,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorDruid",["classToken"]="DRUID",["minLevel"]=15,["name"]="Glyph of the Wild",["nameRu"]="Glyph of the Wild"},{["itemID"]=43332,["spellID"]=57862,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorDruid",["classToken"]="DRUID",["minLevel"]=15,["name"]="Glyph of Thorns",["nameRu"]="Glyph of Thorns"}},["glyphIssues"]={"Glyph of Omen of Clarity"},["trees"]={"Balance","Feral Combat","Restoration"},["source"]="https://www.icy-veins.com/wotlk-classic/feral-druid-tank-pve-spec-builds-talents-glyphs",["calculator"]="https://www.icy-veins.com/wotlk-classic/druid-talent-calculator#tc-sssssWWvvxxzzzDDCCBBBAAFJJJIIIIIKOOORQQQTTTTTUVuuuyYYYZZZZZ~...[[wwwNNN|0K1d2L3w4i5j"}},["sources"]={{["url"]="https://www.icy-veins.com/wotlk-classic/feral-druid-tank-pve-guide",["sha256"]="de0655dc5499338604b12d6a8ebd8efb2915b2757a084b9db1dda820ea05eeef",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/feral-druid-tank-pve-spec-builds-talents-glyphs",["sha256"]="183ec4e8d747a228d20bb16524229260f711319191fc6c93601345e0e2d15a76",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/feral-druid-tank-pve-rotation-cooldowns-abilities",["sha256"]="45f4589deacd9a9fe2a1bcd4e8e1b6d67b8b5307ae5d33a72c06814c79190269",["date"]="2026-10-19"}},["rotationDiagram"]={["kind"]="priority",["heading"]="Single-Target Rotation for Feral Tank Druid",["steps"]={{["spellID"]=50334,["name"]="Berserk",["icon"]="Interface\\Icons\\Ability_Druid_Berserk",["condition"]="Use Berserk when available;"},{["spellID"]=48564,["name"]="Mangle (Bear)",["icon"]="Interface\\Icons\\Ability_Druid_Mangle2",["condition"]="Use Mangle (Bear) when available;"},{["spellID"]=16857,["name"]="Faerie Fire (Feral)",["icon"]="Interface\\Icons\\Spell_Nature_FaerieFire",["condition"]="Use Faerie Fire (Feral) when available;"},{["spellID"]=48568,["name"]="Lacerate",["icon"]="Interface\\Icons\\Ability_Druid_Lacerate",["condition"]="Use (and refresh before it expires) Lacerate until the enemy has 5 stacks ticking;"},{["spellID"]=48479,["name"]="Maul",["icon"]="Interface\\Icons\\Ability_Druid_Maul",["condition"]="Use Maul;"},{["spellID"]=48562,["name"]="Swipe (Bear)",["icon"]="Interface\\Icons\\INV_Misc_MonsterClaw_03",["condition"]="Use Swipe (Bear) if you still have excess Rage after spamming Maul."}}}}},["DRUID:Restoration"]={["classToken"]="DRUID",["sourceSpec"]="Restoration",["role"]="healer",["pve"]={["overview"]={["ruRU"]={"Лекарь с упором на периодическое лечение и мобильность.","Лечение на ходу, сглаживание урона по танку, лечение группы.","Слабее быстрое восстановление после всплеска; важно сохранять ману."},["enUS"]={"Druids are the only class in the game capable of fulling all four roles: tank, healer, ranged DPS, and melee DPS.","Excellent mobility as you can do most of your healing while moving. Multiple heals-over-time can be stacked on the tank to cushion against incoming damage. Strong area healing-over-time with Rejuvenation and Wild Growth blanketing, which procs Revitalize.","Burst healing is low as Druid mostly relies on heals-over-time. Hard to sustain Mana until multiple cost reduction items can be obtained. Utility brought tends to either be weak or able to be brought by more meta classes."}},["rotation"]={["ruRU"]="Это приоритет лечения, не фиксированная ротация. Срочные цели спасайте быстрыми исцелениями, ростом дикой природы лечите группы. Омоложение распределяйте под ожидаемый урон; жизнецвет помогает расходовать проки ясности мысли.",["enUS"]="Our recommendations assume you are running one of the recommended talent builds from the talents page and are playing a max level character. If you are still leveling, please refer to the leveling page for a leveling-specific rotation tailored to your current level. Healers do not have a formal rotation. As such we will display a priority list, instead: Use Nature's Swiftness plus Healing Touch as an emergency heal for players about to die; Use Swiftmend, Regrowth, and Nourish for emergency healing if Nature's Swiftness is on cooldown; Use Lifebloom on the tank to spend Omen of Clarity procs; Use Wild Growth when available on groups of damaged allies; Use Rejuvenation on anyone taking damage, preferably Rogues, Warriors, and Death Knights for maximum Revitalize DPS value. If you are tank healing, keeping your heal-over-time effects rolling on them at all"},["builds"]={{["key"]="pve_0",["title"]="Wrath Restoration Thicc Resto PvE Talent Build (11/0/60)",["talentsString"]="05320001--230023312331502531053313051",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=2238,["rank"]=5,["spellID"]=57814,["tree"]=1,["minLevel"]=10,["maxRank"]=5,["name"]="Genesis",["nameRu"]="Genesis"},{["talentID"]=783,["rank"]=3,["spellID"]=16847,["tree"]=1,["minLevel"]=15,["maxRank"]=3,["name"]="Moonglow",["nameRu"]="Moonglow"},{["talentID"]=1822,["rank"]=2,["spellID"]=35364,["tree"]=1,["minLevel"]=15,["maxRank"]=2,["name"]="Nature's Majesty",["nameRu"]="Nature's Majesty"},{["talentID"]=2240,["rank"]=1,["spellID"]=57865,["tree"]=1,["minLevel"]=20,["maxRank"]=1,["name"]="Nature's Splendor",["nameRu"]="Nature's Splendor"},{["talentID"]=821,["rank"]=2,["spellID"]=17051,["tree"]=3,["minLevel"]=10,["maxRank"]=2,["name"]="Improved Mark of the Wild",["nameRu"]="Improved Mark of the Wild"},{["talentID"]=823,["rank"]=3,["spellID"]=17066,["tree"]=3,["minLevel"]=10,["maxRank"]=3,["name"]="Nature's Focus",["nameRu"]="Nature's Focus"},{["talentID"]=841,["rank"]=2,["spellID"]=17119,["tree"]=3,["minLevel"]=15,["maxRank"]=3,["name"]="Subtlety",["nameRu"]="Subtlety"},{["talentID"]=826,["rank"]=3,["spellID"]=16835,["tree"]=3,["minLevel"]=15,["maxRank"]=3,["name"]="Natural Shapeshifte