новляйте подходящий укус выстрелом химеры. Укус гадюки используйте для давления на ману; не расходуйте возможности остановки лечения одновременно без необходимости.",["enUS"]=""},["builds"]={{["key"]="pvp_0",["title"]="Talent Build (7/51/13)",["talentsString"]="502-005305131030213233105031051-23003020102",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=1382,["rank"]=5,["spellID"]=19556,["tree"]=1,["minLevel"]=10,["maxRank"]=5,["name"]="Improved Aspect of the Hawk",["nameRu"]="Improved Aspect of the Hawk"},{["talentID"]=1624,["rank"]=2,["spellID"]=35030,["tree"]=1,["minLevel"]=15,["maxRank"]=2,["name"]="Focused Fire",["nameRu"]="Focused Fire"},{["talentID"]=1344,["rank"]=5,["spellID"]=19431,["tree"]=2,["minLevel"]=10,["maxRank"]=5,["name"]="Lethal Shots",["nameRu"]="Lethal Shots"},{["talentID"]=1806,["rank"]=3,["spellID"]=34484,["tree"]=2,["minLevel"]=15,["maxRank"]=3,["name"]="Careful Aim",["nameRu"]="Careful Aim"},{["talentID"]=1349,["rank"]=5,["spellID"]=19490,["tree"]=2,["minLevel"]=15,["maxRank"]=5,["name"]="Mortal Shots",["nameRu"]="Mortal Shots"},{["talentID"]=1818,["rank"]=1,["spellID"]=34950,["tree"]=2,["minLevel"]=20,["maxRank"]=2,["name"]="Go for the Throat",["nameRu"]="Go for the Throat"},{["talentID"]=1346,["rank"]=3,["spellID"]=19456,["tree"]=2,["minLevel"]=20,["maxRank"]=3,["name"]="Improved Arcane Shot",["nameRu"]="Improved Arcane Shot"},{["talentID"]=1345,["rank"]=1,["spellID"]=19434,["tree"]=2,["minLevel"]=20,["maxRank"]=1,["name"]="Aimed Shot",["nameRu"]="Aimed Shot"},{["talentID"]=1348,["rank"]=3,["spellID"]=19466,["tree"]=2,["minLevel"]=25,["maxRank"]=3,["name"]="Improved Stings",["nameRu"]="Improved Stings"},{["talentID"]=1351,["rank"]=2,["spellID"]=35102,["tree"]=2,["minLevel"]=30,["maxRank"]=2,["name"]="Concussive Barrage",["nameRu"]="Concussive Barrage"},{["talentID"]=1353,["rank"]=1,["spellID"]=23989,["tree"]=2,["minLevel"]=30,["maxRank"]=1,["name"]="Readiness",["nameRu"]="Readiness"},{["talentID"]=1347,["rank"]=3,["spellID"]