261ea93859fe933e70b31f9cec35ff3825e7f0962a659976d8667b0cfc934c2",["date"]="2026-10-19"}},["rotationDiagram"]={["kind"]="pvp",["steps"]={{["spellID"]=19503,["name"]="Scatter Shot",["icon"]="Interface\\Icons\\Ability_GolemStormBolt",["conditionRu"]="Подготовка контроля; учитывайте убывание эффективности.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=14311,["name"]="Freezing Trap",["icon"]="Interface\\Icons\\Spell_Frost_ChainsOfIce",["conditionRu"]="На цель без периодического урона.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=19434,["name"]="Aimed Shot",["icon"]="Interface\\Icons\\INV_Spear_07",["conditionRu"]="Снижение лечения на атакуемой цели.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=53209,["name"]="Chimera Shot",["icon"]="Interface\\Icons\\Ability_Hunter_ChimeraShot2",["conditionRu"]="Урон и обновление нужного укуса.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=34490,["name"]="Silencing Shot",["icon"]="Interface\\Icons\\Ability_TheBlackArrow",["conditionRu"]="Остановка важного чтения, не просто по готовности.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."}}}}},["HUNTER:Survival"]={["classToken"]="HUNTER",["sourceSpec"]="Survival",["role"]="ranged",["pve"]={["overview"]={["ruRU"]={"Стрелок со взрывным выстрелом, ловушками и магическим уроном.","Хороший ранний урон, массовые атаки и поддержка маны группы.","В поздних комплектах масштабирование может уступать стрельбе."},["enUS"]={"Hunters are master marksmen and, with the help of a fierce animal companion, can deal damage from range without ever letting their target get close. With special tracking abilities, traps, and a wide range of utility spells, Hunters are a great choice for anyone looking","Excellent damage of all types, both on AoE and single target. Brings a raid buff with Hunting Party. Strong utility, including Misdirection and Feign Death. One of the easiest classes to gear early on in Wrath. Incredible leveling speed and","Pet-based class, which means you will need to micro-manage your pet sometimes. Damage falls off slightly in later tiers. Lack of defensive and self-healing cooldowns."}},["rotation"]={["ruRU"]="Приоритет — добивающий и разрывной выстрелы, затем ловушка и поддержание укуса змеи. Не обрывайте периодический эффект разрывного выстрела при проках; верный выстрел заполняет паузы.",["enUS"]="Always start by ensuring all the required buffs are active, you have Aspect of the Dragonhawk up, and Hunter's Mark is on the target. Kill Shot Explosive Shot Explosive Trap Kill Command Maintain Serpent Sting Aimed Shot Steady Shot as your filler. Kill Command is off the GCD. You can simply macro it into other spells to ensure you always use it properly. Hunter AoE revolves entirely around two buttons: Explosive Trap and Volley. Volley is significantly more powerful in Wrath than in TBC, and actually makes Hunter AoE some of the strongest in the game. Properly setting up an Explosive Trap into Volley spam on an AoE pack will do absolutely incredible damage that very few other classes can even hope to compete with."},["builds"]={{["key"]="pve_0",["title"]="Talent Builds for Survival Hunter (0/15/56)",["talentsString"]="-005305101-5000032500033330531135301331",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=1344,["rank"]=5,["spellID"]=19431,["tree"]=2,["minLevel"]=10,["maxRank"]=5,["name"]="Lethal Shots",["nameRu"]="Lethal Shots"},{["talentID"]=1806,["rank"]=3,["spellID"]=34484,["tree"]=2,["minLevel"]=15,["maxRank"]=3,["name"]="Careful Aim",["nameRu"]="Careful Aim"},{["talentID"]=1349,["rank"]=5,["spellID"]=19490,["tree"]=2,["minLevel"]=15,["maxRank"]=5,["name"]="Mortal Shots",["nameRu"]="Morta