lassic/frost-mage-dps-pve-spec-builds-talents-glyphs",["calculator"]="https://www.icy-veins.com/wotlk-classic/mage-talent-calculator#tc-001115555577798dddXXXXXYYYZZZ...~~~[]()))%EF%BD%A6%EF%BD%A6%EF%BD%A6%EF%BD%A7%EF%BD%AB%EF%BD%AB%EF%BD%AB%EF%BD%AD%EF%BD%AE%EF%BD%AE%EF%BD%AE%EF%BD%AE%EF%BD%AE%EF%BD%AF%EF%BD%AF%EF%BD%B0%EF%BD%B0%EF%BD%B2%EF%BD%B1%EF%BD%B1%EF%BD%B1%EF%BD%B3%EF%BD%B3%EF%BD%B3%EF%BD%B4%EF%BD%B4%EF%BD%B4%EF%BD%B4%EF%BD%B4%EF%BD%B5|0h1y2D3b4k5l"}},["sources"]={{["url"]="https://www.icy-veins.com/wotlk-classic/frost-mage-dps-pve-guide",["sha256"]="725ae1307c9c2e11bc119ee2433d8b34c42327428c6c57ce309c875f4234ede7",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/frost-mage-dps-pve-spec-builds-talents-glyphs",["sha256"]="c4b4a557bac0b131e9d7165f829914a3288ab3e029c1b4f8e6557a3c2ce51947",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/frost-mage-dps-pve-rotation-cooldowns-abilities",["sha256"]="6000f86d3aa6a8d7ead497f887cef38e8a8dbe41315d82057c65d357db34e0e8",["date"]="2026-10-19"}},["rotationDiagram"]={["kind"]="combo",["steps"]={{["spellID"]=42842,["name"]="Frostbolt",["icon"]="Interface\\Icons\\Spell_Frost_FrostBolt02",["condition"]="Combo during Fingers of Frost.",["conditionRu"]="Комбинация под проком «Ледяные пальцы»."},{["spellID"]=42842,["name"]="Frostbolt",["icon"]="Interface\\Icons\\Spell_Frost_FrostBolt02",["condition"]="Second Frostbolt during the same proc.",["conditionRu"]="Вторая ледяная стрела под тем же проком."},{["spellID"]=44572,["name"]="Deep Freeze",["icon"]="Interface\\Icons\\Ability_Mage_DeepFreeze",["condition"]="Immediately after the second Frostbolt; not a universal cycle.",["conditionRu"]="Сразу после второй стрелы; не универсальный цикл."}}}},["pvp"]={["overview"]={["ruRU"]={"Заклинатель с сильным контролем, замедлениями и защитой.","Помогает создавать безопасные окна атаки и удерживать дистанцию.","Нужно согласовывать контроль, убывающую эффективность и защитные кулдауны."},["enUS"]={"Frost Mages are one of the strongest specializations in WotLK Classic PvP, having high control, survivability, and burst. They fit into all sorts of compositions and are great in all Arena brackets, Battlegrounds, and World PvP.","",""}},["rotation"]={["ruRU"]="Контроль и дистанция предшествуют урону. Используйте заморозки и проки для коротких окон; холодную хватку распределяйте с учётом повторной защиты и контроля, а не только ради урона.",["enUS"]="Rather than a fixed rotation, Mage gameplay is about setting up crowd control chains, followed by bursting down a target with cooldowns. Use your spells accordingly to keep enemies under control, and eventually burst them down: Keep yourself alive with Ice Barrier, Mana Shield, Frost Nova, Frost Ward, Fire Ward, and Blink. Stay in control of the match with Polymorph, Counterspell, Improved Blizzard (with Permafrost), Freeze, Deep Freeze, and Spellsteal. Apply strong burst damage with Icy Veins and Shatter / Ice Shards / Deep Freeze / Freeze ,which should be combined with Summon Water Elemental, Frostbolt and Ice Lance to create massive instant-cast burst damage on demand. Use Brain Freeze procs to fire a Frostfire Bolt and Fingers of Frost procs to either fire a Frostbolt or a Ice Lance."},["builds"]={{["key"]="pvp_0",["title"]="Deep Frost PvP Mage Talent Build (20/0/51)",["talentsString"]="23032022010203--3533203111203100232102231151",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=74,["rank"]=2,["spellID"]=12592,["tree"]=1,["minLevel"]=10,["maxRank"]=2,["name"]="Arcane Subtlety",["nameRu"]="Arcane Subtlety"},{["talentID"]=76,["rank"]=3,["spellID"]=12840,["tree"]=1,["minLevel"]=10,["maxRank"]=3,["name"]="Arcane Focus",["nameRu"]="Arcane Focus"},{["talentID"]=85,["rank"]=3,["spellID"]=54659,["tree"]=1,["minLevel"]=15,["maxRank"]=3,["name"]="Arcane Fortitude",["nameRu"]="Arcane Fortitude"},{["talentID"]=1650,["rank"]=2,["spellID"]=29444,["tree"]=1,["minLevel"]=15,["maxRank"]=2,["name"]="Magic Absorptio