"glyphIssues"]={},["trees"]={"Holy","Protection","Retribution"},["source"]="https://www.icy-veins.com/wotlk-classic/holy-paladin-pvp-guide",["calculator"]="https://www.icy-veins.com/wotlk-classic/paladin-talent-calculator#tc-000003334422266666588cdddfffffhiii8jjjkkkmmmlnnoommpqqqqqsssttwwwvxyyzz|0w1t2r4k"}},["sources"]={{["url"]="https://www.icy-veins.com/wotlk-classic/holy-paladin-pvp-guide",["sha256"]="5e927a5ee772e965b9f06c95b4decb5d10d97729595a69f969d8557fcfdcfc47",["date"]="2026-10-19"}},["rotationDiagram"]={["kind"]="pvp",["steps"]={{["spellID"]=20473,["name"]="Holy Shock",["icon"]="Interface\\Icons\\Spell_Holy_SearingLight",["conditionRu"]="Срочное лечение или движение.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=4987,["name"]="Cleanse",["icon"]="Interface\\Icons\\Spell_Holy_Renew",["conditionRu"]="Снимайте опасные снимаемые эффекты.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=1044,["name"]="Hand of Freedom",["icon"]="Interface\\Icons\\Spell_Holy_SealOfValor",["conditionRu"]="Помогите союзнику выйти из замедления.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=48785,["name"]="Flash of Light",["icon"]="Interface\\Icons\\Spell_Holy_FlashHeal",["conditionRu"]="Безопасное чтение лечения.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."}}}}},["PALADIN:Protection"]={["classToken"]="PALADIN",["sourceSpec"]="Protection",["role"]="tank",["pve"]={["overview"]={["ruRU"]={"Танк со щитом, массовой угрозой и защитой союзников.","Массовый набор угрозы, благословения и полезные защитные способности.","Ограниченная мобильность; опасен магический урон."},["enUS"]={"Paladins are capable of filling all three roles in Wrath and are competitive at each, Tank, healer, and melee DPS. Each specialization will allow you to fill a specific niche because of the plentiful buffs that no other class can offer.","The best AOE threat generation of any tank. Paladins use Mana and do not have to generate Rage to use their threat-generating abilities while also having nearly unlimited Mana. Strong buffs and utility such as Blessings, Auras, and wipe protection","Highest damage taken in lower gear levels, especially susceptible to caster mobs. Very vulnerable to large numbers of incoming attacks. Limited mobility makes movement challenging."}},["rotation"]={["ruRU"]="Поддерживайте печать и священный щит. Чередуйте короткие и длинные восстановления в схеме 969: щит праведности и молот праведника между правосудием, освящением и священным щитом. Не читайте экзорцизм под ударами.",["enUS"]="If you have not already, please read the Spell Summary page. Knowing how each spell and ability works in detail will greatly increase your understanding of the topics discussed on this page. Protection Paladins are extremely powerful tanks but require you to be ready and know how to handle the various situations you will find yourself in as a tank in order to be able to maximize your threat and survivability. There is fairly little improvising as a Prot Paladin because of their main resource, Mana, being quite limited at times, so it is crucial you have a plan going into each and every fight. This guide assumes you are using the talent build that can be found at Talents page and are playing a max level character. If you are looking for leveling based help please refer to Leveling"},["builds"]={{["key"]="pve_0",["title"]="Talent Build (0/51/20)",["talentsString"]="-05005135200132311333312301-521022012023",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=2185,["rank"]=5,["spellID"]=20266,["tree"]=2,["minLevel"]=10,["maxRank"]=5,["name"]="Divine Strength",["nameRu"]="Divine Strength"},{["talentID"]=1629,["rank"]=5,["spellID"]=20100,["tree"]=2,["minLevel"]=15,["maxRank"]=5,["name"]="Ant