Rank"]=3,["name"]="Crusade",["nameRu"]="Crusade"}},["glyphs"]={{["itemID"]=41092,["spellID"]=54922,["category"]="major",["icon"]="Interface\\Icons\\INV_Glyph_MajorPaladin",["classToken"]="PALADIN",["minLevel"]=15,["name"]="Glyph of Judgement",["nameRu"]="Glyph of Judgement"},{["itemID"]=43869,["spellID"]=56416,["category"]="major",["icon"]="Interface\\Icons\\INV_Glyph_MajorPaladin",["classToken"]="PALADIN",["minLevel"]=50,["name"]="Glyph of Seal of Vengeance",["nameRu"]="Glyph of Seal of Vengeance"},{["itemID"]=43368,["spellID"]=57947,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorPaladin",["classToken"]="PALADIN",["minLevel"]=20,["name"]="Glyph of Sense Undead",["nameRu"]="Glyph of Sense Undead"},{["itemID"]=43367,["spellID"]=57955,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorPaladin",["classToken"]="PALADIN",["minLevel"]=15,["name"]="Glyph of Lay on Hands",["nameRu"]="Glyph of Lay on Hands"}},["glyphIssues"]={"Glyph of Reckoning"},["trees"]={"Holy","Protection","Retribution"},["source"]="https://www.icy-veins.com/wotlk-classic/protection-paladin-tank-pve-spec-builds-talents-glyphs",["calculator"]="https://www.icy-veins.com/wotlk-classic/paladin-talent-calculator#tc-RRSUUXYY...--QQQQQVVrrrrruuuuuwwvwxxxxxyyBCCCDDEEEFGHHHIIIJJJKKKLMMNNNP|0G1f2B3q4g"}},["sources"]={{["url"]="https://www.icy-veins.com/wotlk-classic/protection-paladin-tank-pve-guide",["sha256"]="2e2221b92e985c519fa357c3a47d11f2b5ec2953341aee8d31b39c33cedd159f",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/protection-paladin-tank-pve-spec-builds-talents-glyphs",["sha256"]="6a7d571594d5e775f6f4d04e1bd1875be69c97f6d7343e3c9fe8ccd30e1e301a",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/protection-paladin-tank-pve-rotation-cooldowns-abilities",["sha256"]="fdec8d44f9bd8e49ab4c2da4efbb23e7e86f64fa2a4858d7d5dda814fee75e4c",["date"]="2026-10-19"}}},["pvp"]={["overview"]={["ruRU"]={"Живучий гибрид с длительным давлением и помощью лечением.","Выживаемость, устойчивое давление и поддержка напарника.","Ограниченная мобильность требует правильно расходовать свободу и контроль."},["enUS"]={"Protection Paladin offers some of the strongest sustained damage in any PvP situation in the game along with unmatched tankiness and incredibly strong off healing potential. Protection Paladin in PvP in Wrath is the truest definition of a Hybrid.","",""}},["rotation"]={["ruRU"]="Удерживайте цель дланью свободы и правосудием справедливости. Между атаками помогайте союзникам лечением и защитой; выбирайте наступление или поддержку по ситуации, а не по рейдовой схеме танкования.",["enUS"]="As a Protection Paladin in PvP there is no real set rotation you should be focusing on. The usage of your damaging abilities depends on many factors but the most important thing as a Protection Paladin is to stay on your target as much as you possibly can. As a Paladin your mobility will be quite limited, but if you take advantage of Hand of Freedom to remove all slows, roots, and even stuns thanks to Divine Purpose, along with Judgement of Justice to lessen the effectiveness of your enemies' movespeed bonuses, you can stick to a target quite well. Seal of Vengeance is the primary Seal you will be using in PvP as it synergizes well with your spells all being on short cooldowns and puts more emphasis on your burst potential. This seal is chosen over Command or"},["builds"]={{["key"]="pvp_0",["title"]="Talent Build (0/28/43)",["talentsString"]="-153201302230303-052302500133013221322003",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=1442,["rank"]=1,["spellID"]=63646,["tree"]=2,["minLevel"]=10,["maxRank"]=5,["name"]="Divinity",["nameRu"]="Divinity"},{["talentID"]=2185,["rank"]=5,["spellID"]=20266,["tree"]=2,["minLevel"]=10,["maxRank"]=5,["name"]="Divine Strength",["nameRu"]="Divine Strength"},{["talentID"]=1748,["rank"]=3,["spellID"]=53519,["tree"]=2,["minLevel"]=15,["maxRank"]=3,["name"]="Stoicism",["nameRu