sToken"]="PALADIN",["minLevel"]=15,["name"]="Glyph of Lay on Hands",["nameRu"]="Glyph of Lay on Hands"},{["itemID"]=43368,["spellID"]=57947,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorPaladin",["classToken"]="PALADIN",["minLevel"]=20,["name"]="Glyph of Sense Undead",["nameRu"]="Glyph of Sense Undead"}},["glyphIssues"]={},["trees"]={"Holy","Protection","Retribution"},["source"]="https://www.icy-veins.com/wotlk-classic/retribution-paladin-dps-pve-spec-builds-talents-glyphs",["calculator"]="https://www.icy-veins.com/wotlk-classic/paladin-talent-calculator#tc-rrrrrRRRRRSSTTTUUXWWWWWYY___---...~[[[(()%EF%BD%A6%EF%BD%A6%EF%BD%A6%EF%BD%A7%EF%BD%A7%EF%BD%A7%EF%BD%A8%EF%BD%A8%EF%BD%A9%EF%BD%A9%EF%BD%A9%EF%BD%AA%EF%BD%AB%EF%BD%AB%EF%BD%AB%EF%BD%AC%EF%BD%AC%EF%BD%AC%EF%BD%ADttsssvxxxxy|0f1B2l"}},["sources"]={{["url"]="https://www.icy-veins.com/wotlk-classic/retribution-paladin-dps-pve-guide",["sha256"]="dc3066ce9424156b9cf632bb42e3c8c3807e5867dcdca6c38b30e2fd87276ddb",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/retribution-paladin-dps-pve-spec-builds-talents-glyphs",["sha256"]="b56e278acb6b5ab3941d1bd313121243e22431684431de93d841d3cd89707f06",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/retribution-paladin-dps-pve-rotation-cooldowns-abilities",["sha256"]="44fe2b7930b678aeae006ebc68f50ac6510363f8054d54483963deaafcf0b9f1",["date"]="2026-10-19"}},["rotationDiagram"]={["kind"]="priority",["heading"]="Single Target Rotation",["steps"]={{["spellID"]=31801,["name"]="Seal of Vengeance",["icon"]="Interface\\Icons\\Spell_Holy_SealOfVengeance",["condition"]="Apply Seal of Vengeance to the target if single-target, or use Seal of Command if you will be consistently hitting 2 or more targets;"},{["spellID"]=35395,["name"]="Crusader Strike",["icon"]="Interface\\Icons\\Spell_Holy_CrusaderStrike",["condition"]="Crusader Strike;"},{["spellID"]=53408,["name"]="Judgement of Wisdom",["icon"]="Interface\\Icons\\Ability_Paladin_JudgementBlue",["condition"]="Judgement of Wisdom;"},{["spellID"]=53385,["name"]="Divine Storm",["icon"]="Interface\\Icons\\Ability_Paladin_DivineStorm",["condition"]="Divine Storm;"},{["spellID"]=48819,["name"]="Consecration",["icon"]="Interface\\Icons\\Spell_Holy_InnerFire",["condition"]="Consecration;"},{["spellID"]=48801,["name"]="Exorcism",["icon"]="Interface\\Icons\\Spell_Holy_Excorcism_02",["condition"]="Exorcism;"},{["spellID"]=48817,["name"]="Holy Wrath",["icon"]="Interface\\Icons\\Spell_Holy_Excorcism",["condition"]="Holy Wrath should be the lowest in your priority and only used when you are fighting an Undead or Demon mob type."}}}},["pvp"]={["overview"]={["ruRU"]={"Боец с мощными окнами урона и гибридной поддержкой.","Взрывной урон, помощь лечением, благословения и защита напарника.","Ограниченная мобильность и зависимость от правильного обмена кулдаунами."},["enUS"]={"Retribution Paladin is one of the kings of burst damage in PvP and, among other melee, is unmatched in the utility they can offer to their teammates in the form of buffs, off-healing, and damage mitigation.","",""}},["rotation"]={["ruRU"]="Согласуйте контроль и окно гнева карателя. Поддерживайте контакт с целью свободой и правосудием; мгновенные проки можно потратить на спасение союзника. Защитные ограничения учитывайте до использования наступления.",["enUS"]="As a Retribution Paladin in PvP there is no real set rotation you should be focusing on. The usage of your damaging abilities depends on many factors but the most important thing as a Retribution Paladin is to stay on your target as much as you possibly can. As a Paladin your mobility will be quite limited, but if you take advantage of Hand of Freedom to remove all slows and roots and Judgement of Justice to lessen the effectiveness of your enemies' movespeed bonuses, you can stick to a target quite well. Seal of Righteousness is the primary Seal you will be using in PvP as it synergizes well with your spells all being on short cooldowns and puts more emphasis on your burst potential. You choose this seal over Command because the additional burst damage it causes when"},["builds"]={{["key"]="pvp_0",["title"]="Talent Build (0/19/52)",["talentsString"]="-1532013022-05230250203331322133201321",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=1442,["rank"]=1,["spellID"]=63646,["tree"]=2,["minLevel"]=10,["maxRank"]=5,["name"]="Divinity",["nameRu"]="Divinity"},{["talentID"]=2185,["rank"]=5,["spellID"]=20266,["tree"]=2,["minLevel"]=10,["maxRank"]=5,["name"]="Divine Strength",["nameRu"]="Divine Strength"},{["talentID"]=1748,["rank"]=3,["spellID"]=53519,["tree"]=2,["minLevel"]=15,["maxRank"]=3,["name"]="Stoicism",["nameRu"]="Stoicism"},{["talentID"]=1425,["rank"]=2,["spellID"]=20175,["tree"]=2,["minLevel"]=15,["maxRank"]=2,["name"]="Guardian's Favor",["nameRu"]="Guardian's Favor"},{["talentID"]=2280,["rank"]=1,["spellID"]=64205,["tree"]=2,["minLevel"]=20,["maxRank"]=1,["name"]="Divine Sacrifice",["nameRu"]="Divine Sacrifice"},{["talentID"]=1501,["rank"]=3,["spellID"]=20470,["tree"]=2,["minLevel"]=20,["maxRank"]=3,["name"]="Improved Righteous Fury",["nameRu"]="Improved Righteous Fury"},{["talentID"]=2281,["rank"]=2,["spellID"]=53530,["tree"]=2,["minLevel"]=25,["maxRank"]=2,["name"]="Divine Guardian",["nameRu"]="Divine Guardian"},{["talentID"]=1521,["rank"]=2,["spellID"]=20488,["tree"]=2,["minLevel"]=25,["maxRank"]=2,["name"]="Improved Hammer of Justice",["nameRu"]="Improved Hammer of Justice"},{["talentID"]=1407,["rank"]=5,["spellID"]=20105,["tree"]=3,["minLevel"]=10,["maxRank"]=5,["name"]="Benediction",["nameRu"]="Benediction"},{["talentID"]=1631,["rank"]=2,["spellID"]=25957,["tree"]=3,["minLevel"]=15,["maxRank"]=2,["name"]="Improved Judgements",["nameRu"]="Improved Judgements"},{["talentID"]=1464,["rank"]=3,["spellID"]=20337,["tree"]=3,["minLevel"]=15,["maxRank"]=3,["name"]="Heart of the Crusader",["nameRu"]="Heart of the Crusader"},{["talentID"]=1633,["rank"]=2,["spellID"]=26016,["