sToken"]="PRIEST",["minLevel"]=20,["name"]="Glyph of Shackle Undead",["nameRu"]="Glyph of Shackle Undead"},{["itemID"]=43371,["spellID"]=58009,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorPriest",["classToken"]="PRIEST",["minLevel"]=15,["name"]="Glyph of Fortitude",["nameRu"]="Glyph of Fortitude"}},["glyphIssues"]={},["trees"]={"Discipline","Holy","Shadow"},["source"]="https://www.icy-veins.com/wotlk-classic/discipline-priest-pvp-guide",["calculator"]="https://www.icy-veins.com/wotlk-classic/priest-talent-calculator#tc-0000033347888666aaadddddeffgggicchmmkhhonnnqqqqqrpplll2ssvvvvvzzzxuuu22|0y1C2e3E4p5c"}},["sources"]={{["url"]="https://www.icy-veins.com/wotlk-classic/discipline-priest-pvp-guide",["sha256"]="ea3036d724cb11eb593cd46ed96c796821438805559683a8b422d93a2bf6c6ee",["date"]="2026-10-19"}},["rotationDiagram"]={["kind"]="pvp",["steps"]={{["spellID"]=10900,["name"]="Power Word: Shield",["icon"]="Interface\\Icons\\Spell_Holy_PowerWordShield",["conditionRu"]="Предупреждайте входящий урон.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=47540,["name"]="Penance",["icon"]="Interface\\Icons\\Spell_Holy_Penance",["conditionRu"]="Срочное направленное лечение.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=988,["name"]="Dispel Magic",["icon"]="Interface\\Icons\\Spell_Holy_DispelMagic",["conditionRu"]="Снятие опасного эффекта или усиления противника.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=10890,["name"]="Psychic Scream",["icon"]="Interface\\Icons\\Spell_Shadow_PsychicScream",["conditionRu"]="Контроль или спасение от давления.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."}}}}},["PRIEST:Holy"]={["classToken"]="PRIEST",["sourceSpec"]="Holy",["role"]="healer",["pve"]={["overview"]={["ruRU"]={"Гибкий лекарь с богатым набором группового лечения.","Быстро восстанавливает группу, легко меняет способ лечения под ситуацию.","Высокая зависимость от маны и конкуренция за экипировку."},["enUS"]={"Holy Priest continues down the path of being an excellent AoE healer, gaining even more tools to improve their healing output capabilities. As a Holy Priest, your primary job will be to keep the entire raid healthy and quickly heal up raid-wide damage.","Extremely high AoE healing, capable of quickly topping up the raid. Very diverse healing kit, allowing multiple different playstyles. Great flexibility, allowing them cover any healing needs.","Gearing is extremely difficult as they share most of their gear with casters. Very Mana-reliant, easily can go OoM quickly without proper play. Struggles to keep up with other healers as gear improves."}},["rotation"]={["ruRU"]="Поддерживайте молитву восстановления и используйте круг исцеления по групповому урону. Обновление — под длительный урон, молитва исцеления — по пострадавшей группе. Быстрое и связующее исцеление используйте по срочным целям.",["enUS"]="As a Holy Priest, you will constantly be changing between healing a single person taking high damage, typically a tank, and healing multiple people taking damage from a raid mechanic. Below you will find the different rotations and spell priorities depending on the healing situation you are in. Renew — Remains a powerful heal-over-time. Be sure to keep this on targets you know will be taking constant damage. Prayer of Mending — This spell remains extremely powerful, even getting buffed in WotLK. Be sure to use this as much as possible. Greater Heal — A slow, but powerful heal. Use this when a big burst of damage is about to land on a target, or if the target will not die before the longer cast time ends and needs a large heal. Flash Heal — This is your main filler"},["builds"]={{["key"]="pve_0",["title"]="Talent Builds for Holy Priest in Wrath of the Lich Ki