jor",["icon"]="Interface\\Icons\\INV_Glyph_MajorPriest",["classToken"]="PRIEST",["minLevel"]=15,["name"]="Glyph of Shadow Word: Pain",["nameRu"]="Glyph of Shadow Word: Pain"},{["itemID"]=43371,["spellID"]=58009,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorPriest",["classToken"]="PRIEST",["minLevel"]=15,["name"]="Glyph of Fortitude",["nameRu"]="Glyph of Fortitude"},{["itemID"]=43370,["spellID"]=57987,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorPriest",["classToken"]="PRIEST",["minLevel"]=34,["name"]="Glyph of Levitate",["nameRu"]="Glyph of Levitate"},{["itemID"]=43374,["spellID"]=58228,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorPriest",["classToken"]="PRIEST",["minLevel"]=66,["name"]="Glyph of Shadowfiend",["nameRu"]="Glyph of Shadowfiend"}},["glyphIssues"]={},["trees"]={"Discipline","Holy","Shadow"},["source"]="https://www.icy-veins.com/wotlk-classic/shadow-priest-dps-pve-spec-builds-talents-glyphs",["calculator"]="https://www.icy-veins.com/wotlk-classic/priest-talent-calculator#tc-VVVVVTTTUUXXYYY.~~[[[(%EF%BD%A6%EF%BD%A8%EF%BD%A8%EF%BD%A8%EF%BD%A7%EF%BD%A7%EF%BD%A9%EF%BD%AA%EF%BD%AA%EF%BD%AA%EF%BD%AA%EF%BD%AA%EF%BD%AB%EF%BD%AC%EF%BD%AC%EF%BD%AC%EF%BD%AE__%EF%BD%AF11111333447666%EF%BD%AB%EF%BD%AF%EF%BD%AF%EF%BD%B0%EF%BD%B0%EF%BD%B0%EF%BD%B0%EF%BD%B0%EF%BD%B1%EF%BD%A6-----|0n2h3c4v5E1q"}},["sources"]={{["url"]="https://www.icy-veins.com/wotlk-classic/shadow-priest-dps-pve-guide",["sha256"]="113a0ed270725abca47a41ec23aac65e0127ae5e9b31040453d72ca1a7aeebe5",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/shadow-priest-dps-pve-spec-builds-talents-glyphs",["sha256"]="c9744291eefb4e4cff6b7aa57bcf8b24e6a38217bbcb8bf51ca62e178b7b4771",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/shadow-priest-dps-pve-rotation-cooldowns-abilities",["sha256"]="e62a4174d764eb4af1c8cf07958aa48eec551fb4007136fedf489da7dfaa8a05",["date"]="2026-10-19"}},["rotationDiagram"]={["kind"]="priority",["heading"]="Shadow Priest Single-Target Damage Rotation in Wrath of the Lich King",["steps"]={{["spellID"]=34914,["name"]="Vampiric Touch",["icon"]="Interface\\Icons\\Spell_Holy_Stoicism",["condition"]="Vampiric Touch — This is your main priority to keep up. Whenever you use Mind Blast while Vampiric Touch is up, you will buff up to 10 players with Replenishment."},{["spellID"]=48300,["name"]="Devouring Plague",["icon"]="Interface\\Icons\\Spell_Shadow_DevouringPlague",["condition"]="Devouring Plague — A huge part of your damage, be sure to keep it up as much as possible. The combination of this being an instant-cast spell and the Improved Devouring Plague talent make this a decent spell to cast when moving."},{["spellID"]=10947,["name"]="Mind Blast",["icon"]="Interface\\Icons\\Spell_Shadow_UnholyFrenzy",["condition"]="Mind Blast — Use this on cooldown as it deals very high damage and procs some of your talents such as Improved Spirit Tap. With T10-4set, you will only cast Mind Blast whenever you have no increased cast speed buffs."},{["spellID"]=58381,["name"]="Mind Flay",["icon"]="Interface\\Icons\\Spell_Shadow_SiphonMana",["condition"]="Mind Flay — Mostly a filler spell. Mind Flay has 3 ticks of damage over the course of the channel. If a higher priority spell needs to be cast while you are channeling Mind Flay, make sure to stop casting right after one of these ticks goes off. Like Mind Blast, this will proc Improved Spirit Tap, but Mind Flay will also proc Pain and Suffering and constantly refresh the duration of your Shadow Word: Pain."},{["spellID"]=48158,["name"]="Shadow Word: Death",["icon"]="Interface\\Icons\\Spell_Shadow_DemonicFortitude",["condition"]="Shadow Word: Death — Use this when moving only."},{["spellID"]=25367,["name"]="Shadow Word: Pain",["icon"]="Interface\\Icons\\Spell_Shadow_ShadowWordPain",["condition"]="Shadow Word: Pain — You have this at the bottom of the list as it should always be refreshed with your talent Pain and Suffering. That being said, you still need to manually apply it the first time, but it should remain up for the rest of the fight after that. Be sure to wait until you have 5 stacks of Shadow Weaving before you apply this as it will snapshot the stacks and keep the damage buff even when refreshed."}}}},["pvp"]={["overview"]={["ruRU"]={"Заклинатель давления с важной наступательной и защитной поддержкой.","Периодический урон сочетается с полезными инструментами для союзников.","Если заниматься только уроном, теряется значительная часть ценности спека."},["enUS"]={"Shadow Priest is a strong damage dealer in PvP that offers great utility both offensively and defensively. Unlike other damage dealing classes, you will need to focus greatly on this utility in PvP situations to maximize the full potential of a Shadow Priest.","Both offensive and defensive magic dispels. Powerful damage-over-time spells that can be applied to multiple enemies. Can throw out heals in an emergency situation to save an ally.","Usually gets focused in arenas as you only have one defensive cooldown. Relies on dispellable DoTs to deal the majority of your damage. Has Mana issues if fights do not end quickly, especially in low gear."}},["rotation"]={["ruRU"]="Поддерживайте давление, но вовремя переключайтесь на снятие эффектов, контроль и помощь союзнику. Защитную форму используйте под опасный ответ; не расходуйте её только ради продолжения атаки.",["enUS"]=""},["builds"]={{["key"]="pvp_0",["title"]="Talent Build For PvP Shadow Priest in Wrath of the Lich King (20/0/51)",["talentsString"]="50332031003--005323231223112023102311251",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=342,["rank"]=5,["spellID"]=14791,["tree"]=1,["minLevel"]=10,["maxRank"]=5,["name"]="Unbreakable Will",["nameRu"]="Unbreakable Will"},{["talentID"]=352,["rank"]=3,["spellID"]=14785,["tree"]=1,["minLevel"]=15,["maxRank"]=3,["name"]="Silent Resolve",["nameRu"]="Silent Resolve"},{["talentID"]=346,["rank"]=3,["spellID"]=147