am"]={["kind"]="pvp",["steps"]={{["spellID"]=34914,["name"]="Vampiric Touch",["icon"]="Interface\\Icons\\Spell_Holy_Stoicism",["conditionRu"]="Поддерживайте давление, когда безопасно читать.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=25367,["name"]="Shadow Word: Pain",["icon"]="Interface\\Icons\\Spell_Shadow_ShadowWordPain",["conditionRu"]="Не наносите периодический урон в цель контроля.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=48300,["name"]="Devouring Plague",["icon"]="Interface\\Icons\\Spell_Shadow_DevouringPlague",["conditionRu"]="Давление по выбранной цели.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=10947,["name"]="Mind Blast",["icon"]="Interface\\Icons\\Spell_Shadow_UnholyFrenzy",["conditionRu"]="Безопасное окно чтения.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=15487,["name"]="Silence",["icon"]="Interface\\Icons\\Spell_Shadow_ImpPhaseShift",["conditionRu"]="Остановите важное лечение или заклинание.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."}}}}},["ROGUE:Assassination"]={["classToken"]="ROGUE",["sourceSpec"]="Assassination",["role"]="melee",["pve"]={["overview"]={["ruRU"]={"Боец ближнего боя с ядами, расправой и отравлением.","Сильный длительный урон по одной цели; меньше зависит от экипировки, чем бой.","Потери при смене цели; ограниченные короткие окна взрывного урона."},["enUS"]={"Rogues, for the most part, bring a very useful set of tools to parties and raid groups alike and are desirable for almost all content throughout the Wrath of the Lich King expansion.","Brings Master Poisoner to the raid. Extremely high single-target sustained damage. Does not require as much gear as Combat. Brings Tricks of the Trade to the raid.","Low damage when switching targets. AoE situations are more difficult for Assassination than Combat. No burst damage."}},["rotation"]={["ruRU"]="Поддерживайте мясорубку и необходимые ослабления; расправа набирает приёмы, отравление расходует их. Учитывайте срок действия усиления отравления и не переполняйте энергию. Ослабление брони берите на себя только по назначению.",["enUS"]="If you have not already, please read the Spell Summary page. Knowing how each spell and ability works in detail will greatly increase your understanding of the topics discussed on this page. Your main role as an Assassination Rogue is to simply put out as much damage as you can for the most part, with the main exception being when there is no Warrior in your group, in which case you will be applying the Armor debuff with Expose Armor. For the most part, the rotation is fairly simply and revolves around the building and spending of Combo Points with Mutilate and Envenom. Your rotation will vary slightly depending on whether you have a Warrior in your group or not. If there is a Warrior in your group or another Rogue applying Expose Armor, then you will not need to"},["builds"]={{["key"]="pve_0",["title"]="Boss-Damage Assassination Talent Build (51/13/7)",["talentsString"]="005303005352100520103331051-005005003-502",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=270,["rank"]=5,["spellID"]=14142,["tree"]=1,["minLevel"]=10,["maxRank"]=5,["name"]="Malice",["nameRu"]="Malice"},{["talentID"]=273,["rank"]=3,["spellID"]=14161,["tree"]=1,["minLevel"]=15,["maxRank"]=3,["name"]="Ruthlessness",["nameRu"]="Ruthlessness"},{["talentID"]=277,["rank"]=3,["spellID"]=13866,["tree"]=1,["minLevel"]=15,["maxRank"]=3,["name"]="Puncturing Wounds",["nameRu"]="Puncturing Wounds"},{["talentID"]=269,["rank"]=5,["spellID"]=14137,["tree"]=1,["minLevel"]=20,["maxRank"]=5,["name"]="Lethality",["nameRu"]="Lethality"},{["talentID"]=682,["rank"]=3,["spellID"]=16515,["tree"]=1