Glyph_MajorRogue",["classToken"]="ROGUE",["minLevel"]=15,["name"]="Glyph of Slice and Dice",["nameRu"]="Glyph of Slice and Dice"},{["itemID"]=45768,["spellID"]=63268,["category"]="major",["icon"]="Interface\\Icons\\INV_Glyph_MajorRogue",["classToken"]="ROGUE",["minLevel"]=50,["name"]="Glyph of Mutilate",["nameRu"]="Glyph of Mutilate"},{["itemID"]=45767,["spellID"]=63256,["category"]="major",["icon"]="Interface\\Icons\\INV_Glyph_MajorRogue",["classToken"]="ROGUE",["minLevel"]=75,["name"]="Glyph of Tricks of the Trade",["nameRu"]="Glyph of Tricks of the Trade"}},["glyphIssues"]={},["trees"]={"Assassination","Combat","Subtlety"},["source"]="https://www.icy-veins.com/wotlk-classic/assassination-rogue-dps-pve-spec-builds-talents-glyphs",["calculator"]="https://www.icy-veins.com/wotlk-classic/rogue-talent-calculator#tc-2222255533388888aaaaa999cbbfffffggillkkktttttwwwwwzzzzzCCCTTuuFTTTVnmmm|0k1z2H"}},["sources"]={{["url"]="https://www.icy-veins.com/wotlk-classic/assassination-rogue-dps-pve-guide",["sha256"]="294e4a2465e8f792590dfc7162b37e437b1f9c7980c94499db56db5586bb55a1",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/assassination-rogue-dps-pve-spec-builds-talents-glyphs",["sha256"]="4c74f47668d803ffb4903bff107eba7eb9e378839863ba59a641ee59d3a9a116",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/assassination-rogue-dps-pve-rotation-cooldowns-abilities",["sha256"]="50d690b96c86b31e8e730b420b075686ac4d2b678cbb0fb506c80acb4386e23e",["date"]="2026-10-19"}},["rotationDiagram"]={["kind"]="cycle",["steps"]={{["spellID"]=48666,["name"]="Mutilate",["icon"]="Interface\\Icons\\Ability_Rogue_ShadowStrikes",["condition"]="Build combo points at 1-3 points; maintain buffs.",["conditionRu"]="При 1-3 приёмах набирайте приёмы; сохраняйте усиления."},{["spellID"]=57993,["name"]="Envenom",["icon"]="Interface\\Icons\\Ability_Rogue_Disembowel",["condition"]="At 4-5 combo points after the opener.",["conditionRu"]="При 4-5 приёмах после открытия боя."}}}}},["ROGUE:Combat"]={["classToken"]="ROGUE",["sourceSpec"]="Combat",["role"]="melee",["pve"]={["overview"]={["ruRU"]={"Боец ближнего боя с оружейными атаками и сильными кулдаунами.","Урон по близким целям, всплески под выбросом адреналина и полезное ослабление.","Сильнее зависит от оружия и экипировки."},["enUS"]={"Rogue, for the most part, brings a very useful set of tools to parties and raid groups alike and are desirable for almost all content throughout the Wrath of the Lich King expansion.","Brings the Savage Combat debuff to the raid. Very high AoE and burst damage. Brings the Tricks of the Trade buff to the raid.","Struggles in single-target sustained damage compared to Assassination. Requires better gear than Assassination."}},["rotation"]={["ruRU"]="Поддерживайте мясорубку; коварный удар набирает приёмы, завершающие удары выбираются по сроку кровотечения и условиям боя. Чередуйте выброс адреналина и череду убийств с учётом энергии и безопасного положения.",["enUS"]="If you have not already, please read the Spell Summary page. Knowing how each spell and ability works in detail will greatly increase your understanding of the topics discussed on this page. Your main role as an Combat Rogue is to simply put out as much damage as you can, with massive amounts of burst damage available during Adrenaline Rush windows. Your rotation will vary slightly depending on whether you have a Warrior in your group or not. If there is a Warrior in your group or another Rogue applying Expose Armor, then you will not need to use it yourself. In this case, your rotation will consist of juggling the Slice and Dice buff and Rupture debuff. Maintain both of them while using Sinister Strike to generate Combo Points. If you have any additional Combo Points and do not"},["builds"]={{["key"]="pve_0",["title"]="Standard Combat Talent Build (20/51/0)",["talentsString"]="00532000514-0252051050035010223100501251-",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=27