Safe Fall"},{["itemID"]=43380,["spellID"]=58038,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorRogue",["classToken"]="ROGUE",["minLevel"]=22,["name"]="Glyph of Vanish",["nameRu"]="Glyph of Vanish"}},["glyphIssues"]={},["trees"]={"Assassination","Combat","Subtlety"},["source"]="https://www.icy-veins.com/wotlk-classic/combat-rogue-dps-pve-spec-builds-talents-glyphs",["calculator"]="https://www.icy-veins.com/wotlk-classic/rogue-talent-calculator#tc-2222233344688888999aaaaabbcfffffggikkksstttttwwwwwuuxxzzzzzCCCDFHHIIKJJ|0H1F2G3s4y5t"}},["sources"]={{["url"]="https://www.icy-veins.com/wotlk-classic/combat-rogue-dps-pve-guide",["sha256"]="9f5f7c4f93bbc73e78309e24c004502e1cb84152457bb4cecdeef9c81e45a5e0",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/combat-rogue-dps-pve-spec-builds-talents-glyphs",["sha256"]="4ac93ecd33f7d1b94416b49d49f7087a779e3227aabc22bcafce00736a886a48",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/combat-rogue-dps-pve-rotation-cooldowns-abilities",["sha256"]="e55d72875e29b06dcd4fafbbb3a0373c2053eaeb0799594f43a66695542ee4e2",["date"]="2026-10-19"}},["rotationDiagram"]={["kind"]="priority",["steps"]={{["spellID"]=6774,["name"]="Slice and Dice",["icon"]="Interface\\Icons\\Ability_Rogue_SliceDice",["condition"]="Maintain Slice and Dice; requires combo points.",["conditionRu"]="Поддерживайте мясорубку; нужны приёмы."},{["spellID"]=48672,["name"]="Rupture",["icon"]="Interface\\Icons\\Ability_Rogue_Rupture",["condition"]="Maintain Rupture, considering available combo points.",["conditionRu"]="Поддерживайте кровотечение, учитывая число приёмов."},{["spellID"]=48638,["name"]="Sinister Strike",["icon"]="Interface\\Icons\\Spell_Shadow_RitualOfSacrifice",["condition"]="Build combo points when maintained effects need no refresh.",["conditionRu"]="Набор приёмов, когда поддерживаемые эффекты не требуют обновления."},{["spellID"]=48668,["name"]="Eviscerate",["icon"]="Interface\\Icons\\Ability_Rogue_Eviscerate",["condition"]="Spare combo points when Rupture needs no refresh.",["conditionRu"]="Свободные приёмы, когда не нужно обновлять разрыв."}}}}},["ROGUE:Subtlety"]={["classToken"]="ROGUE",["sourceSpec"]="Subtlety",["role"]="melee",["pve"]={["overview"]={["ruRU"]={"Боец ближнего боя с контролем, скрытностью и теневыми приёмами.","Взрывной урон, полезные уловки и обход отдельных механик.","В PvE урон заметно уступает другим специализациям разбойника."},["enUS"]={"Rogue, for the most part, brings a very useful set of tools to parties and raid groups alike, but Subtlety is less suited to PvE than the other specs available to Rogue. Due to this, it is generally less desirable in a PvE or raid","Provides the raid with the Hemorrhage debuff. They can talent to improve the Tricks of the Trade buff that they provide. Solid burst damage. Can soak and negate raid mechanics to make fights easier.","Damage is lower than other Rogue specializations, preventing them from being \"competitive\"."}},["rotation"]={["ruRU"]="По назначению поддерживайте ослабление брони, затем мясорубку и рваную рану. Шаг сквозь тень усиливает рваную рану; лишние приёмы расходуйте на потрошение. Этот вариант не следует считать рейдовым лидером по урону.",["enUS"]="If you have not already, please read the Spell Summary page. Knowing how each spell and ability works in detail will greatly increase your understanding of the topics discussed on this page. Given the lower output of Subtlety compared to the other two Rogue specializations, it is normally chosen as the Expose Armor user when no Warrior is present. You do not generally have enough need to warrant using the Combo Points elsewhere and they can instead be used on maintaining the debuff, given the surplus you will likely have. Your first priority will be to maintain Expose Armor, followed by Slice and Dice and Rupture. You should use Shadowstep prior to each cast of Rupture to get the 20% bonus damage on your strongest ability. You should spend your Combo Points on maintaining these and, if you have any"},["builds"]={{["key"]="pve_0",["title"]="Standard Subtlety Talent Build (19/0/52)",["talentsString"]="00532000513--5020032130320121350115031251",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=270,["rank"]=5,["spellID"]=14142,["tree"]=1,["minLevel"]=10,["maxRank"]=5,["name"]="Malice",["nameRu"]="Malice"},{["talentID"]=273,["rank"]=3,["spellID"]=14161,["tree"]=1,["minLevel"]=15,["maxRank"]=3,["name"]="Ruthlessness",["nameRu"]="Ruthlessness"},{["talentID"]=2068,["rank"]=2,["spellID"]=51633,["tree"]=1,["minLevel"]=15,["maxRank"]=2,["name"]="Blood Spatter",["nameRu"]="Blood Spatter"},{["talentID"]=269,["rank"]=5,["spellID"]=14137,["tree"]=1,["minLevel"]=20,["maxRank"]=5,["name"]="Lethality",["nameRu"]="Lethality"},{["talentID"]=682,["rank"]=1,["spellID"]=16513,["tree"]=1,["minLevel"]=25,["maxRank"]=3,["name"]="Vile Poisons",["nameRu"]="Vile Poisons"},{["talentID"]=268,["rank"]=3,["spellID"]=14115,["tree"]=1,["minLevel"]=25,["maxRank"]=5,["name"]="Improved Poisons",["nameRu"]="Improved Poisons"},{["talentID"]=2244,["rank"]=5,["spellID"]=58425,["tree"]=3,["minLevel"]=10,["maxRank"]=5,["name"]="Relentless Strikes",["nameRu"]="Relentless Strikes"},{["talentID"]=261,["rank"]=2,["spellID"]=14072,["tree"]=3,["minLevel"]=10,["maxRank"]=2,["name"]="Opportunity",["nameRu"]="Opportunity"},{["talentID"]=244,["rank"]=3,["spellID"]=14063,["tree"]=3,["minLevel"]=15,["maxRank"]=3,["name"]="Camouflage",["nameRu"]="Camouflage"},{["talentID"]=247,["rank"]=2,["spellID"]=14066,["tree"]=3,["minLevel"]=20,["maxRank"]=2,["name"]="Elusiveness",["nameRu"]="Elusiveness"},{["talentID"]=303,["rank"]=1,["spellID"]=14278,["tree"]=3,["minLevel"]=20,["maxRank"]=1,["name"]="Ghostly Strike",["nameRu"]="Ghostly Strike"},{["talentID"]=1123,["rank"]=3,["spellID"]=14173,["tree"]=3,["minLevel"]=20,["maxRank"]=3,["name"]="Serrated Blades",["nameRu"]="Serrated Blades"},{["talentID"]=245,["rank"]=3,["spellID"]=13980,["tree"]=3,["m