["icon"]="Interface\\Icons\\Ability_Warrior_Riposte",["condition"]="If another player is not providing the armor debuff.",["conditionRu"]="Если ослабление брони не обеспечивает другой игрок."},{["spellID"]=6774,["name"]="Slice and Dice",["icon"]="Interface\\Icons\\Ability_Rogue_SliceDice",["condition"]="Maintain the buff; requires combo points.",["conditionRu"]="Поддерживайте усиление; нужны приёмы."},{["spellID"]=36554,["name"]="Shadowstep",["icon"]="Interface\\Icons\\Ability_Rogue_Shadowstep",["condition"]="Before applying Rupture.",["conditionRu"]="Перед наложением разрыва."},{["spellID"]=48672,["name"]="Rupture",["icon"]="Interface\\Icons\\Ability_Rogue_Rupture",["condition"]="Maintain the bleed.",["conditionRu"]="Поддерживайте кровотечение."},{["spellID"]=48668,["name"]="Eviscerate",["icon"]="Interface\\Icons\\Ability_Rogue_Eviscerate",["condition"]="Only with spare combo points.",["conditionRu"]="Только свободные приёмы."},{["spellID"]=48660,["name"]="Hemorrhage",["icon"]="Interface\\Icons\\Spell_Shadow_LifeDrain",["condition"]="Spend energy when no finisher is needed.",["conditionRu"]="Расход энергии, если завершающий приём сейчас не нужен."}}}},["pvp"]={["overview"]={["ruRU"]={"Боец контроля и коротких атакующих окон из скрытности.","Большой набор инструментов для перехвата инициативы.","Высокие требования к практике, ресурсам и координации."},["enUS"]={"Subtlety Rogue is synonymous with arena PvP; any experienced PvP player has Subtlety Rogue come to mind when thinking about PvP. Having a massive arsenal of tools available to them, Rogues can counter their enemies in almost any situation, always having a way to turn","Powerful crowd control; can easily setup kills. Extremely high burst damage when cooldowns are available. Highly diverse toolkit, almost always having an ability to counter your enemies. Has multiple ways to interrupt casts, easily controlling enemies who need to hard","No real form of self-sustain. Gearing and playstyle are fully offensive, leaving you vulnerable outside of defensive cooldowns. Very difficult to properly play; requires nearly perfect execution acquired from practice. Doesn't do well in large engagements, such as 5v5 arenas"}},["rotation"]={["ruRU"]="Планируйте открытие, контроль и повторный вход в скрытность. Не накладывайте конфликтующие оглушения без причины; урон должен приходиться в подготовленное окно, а защиту нужно сохранять под ответ противника.",["enUS"]=""},["builds"]={{["key"]="pvp_0",["title"]="Talent Build For PvP Subtlety Rogue in Wrath of the Lich King (12/3/56)",["talentsString"]="3023031-3-5120212030320121350135231251",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=276,["rank"]=3,["spellID"]=14164,["tree"]=1,["minLevel"]=10,["maxRank"]=3,["name"]="Improved Eviscerate",["nameRu"]="Improved Eviscerate"},{["talentID"]=270,["rank"]=2,["spellID"]=14139,["tree"]=1,["minLevel"]=10,["maxRank"]=5,["name"]="Malice",["nameRu"]="Malice"},{["talentID"]=273,["rank"]=3,["spellID"]=14161,["tree"]=1,["minLevel"]=15,["maxRank"]=3,["name"]="Ruthlessness",["nameRu"]="Ruthlessness"},{["talentID"]=277,["rank"]=3,["spellID"]=13866,["tree"]=1,["minLevel"]=15,["maxRank"]=3,["name"]="Puncturing Wounds",["nameRu"]="Puncturing Wounds"},{["talentID"]=382,["rank"]=1,["spellID"]=14983,["tree"]=1,["minLevel"]=20,["maxRank"]=1,["name"]="Vigor",["nameRu"]="Vigor"},{["talentID"]=203,["rank"]=3,["spellID"]=13792,["tree"]=2,["minLevel"]=10,["maxRank"]=3,["name"]="Improved Gouge",["nameRu"]="Improved Gouge"},{["talentID"]=2244,["rank"]=5,["spellID"]=58425,["tree"]=3,["minLevel"]=10,["maxRank"]=5,["name"]="Relentless Strikes",["nameRu"]="Relentless Strikes"},{["talentID"]=241,["rank"]=1,["spellID"]=13958,["tree"]=3,["minLevel"]=10,["maxRank"]=3,["name"]="Master of Deception",["nameRu"]="Master of Deception"},{["talentID"]=261,["rank"]=2,["spellID"]=14072,["tree"]=3,["minLevel"]=10,["maxRank"]=2,["name"]="Opportunity",["nameRu"]="Opportunity"},{["talentID"]=262,["rank"]=2,["spellID"]=14094,["