["minLevel"]=15,["name"]="Glyph of Lightning Bolt",["nameRu"]="Glyph of Lightning Bolt"},{["itemID"]=45776,["spellID"]=63280,["category"]="major",["icon"]="Interface\\Icons\\INV_Glyph_MajorShaman",["classToken"]="SHAMAN",["minLevel"]=50,["name"]="Glyph of Totem of Wrath",["nameRu"]="Glyph of Totem of Wrath"},{["itemID"]=44923,["spellID"]=62132,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorShaman",["classToken"]="SHAMAN",["minLevel"]=70,["name"]="Glyph of Thunderstorm",["nameRu"]="Glyph of Thunderstorm"},{["itemID"]=43386,["spellID"]=58063,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorShaman",["classToken"]="SHAMAN",["minLevel"]=20,["name"]="Glyph of Water Shield",["nameRu"]="Glyph of Water Shield"},{["itemID"]=43385,["spellID"]=58059,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorShaman",["classToken"]="SHAMAN",["minLevel"]=30,["name"]="Glyph of Renewed Life",["nameRu"]="Glyph of Renewed Life"}},["glyphIssues"]={},["trees"]={"Elemental","Enhancement","Restoration"},["source"]="https://www.icy-veins.com/wotlk-classic/elemental-shaman-dps-pve-spec-builds-talents-glyphs",["calculator"]="https://www.icy-veins.com/wotlk-classic/shaman-talent-calculator#tc-1111122267777788999caabdddeeeeefgggiijjjlnnnnnorrttttthhcmmm33xrrrwww3c|0c1f3H4o5t2B"}},["sources"]={{["url"]="https://www.icy-veins.com/wotlk-classic/elemental-shaman-dps-pve-guide",["sha256"]="7e52dc8c86628a31ac7fe28dd698ae50181686818c72683d75a3202319d6d3fd",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/elemental-shaman-dps-pve-spec-builds-talents-glyphs",["sha256"]="c73f7fab76315acda8581049efae471b3fd339413004fe0b611a8bde2c2b3037",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/elemental-shaman-dps-pve-rotation-cooldowns-abilities",["sha256"]="5a45d99d641ae5344fcd52e60710f6c990806ecfb7bb05656c25d12b2ad4df63",["date"]="2026-10-19"}},["rotationDiagram"]={["kind"]="priority",["heading"]="Single-Target Rotation for Elemental Shamans",["steps"]={{["spellID"]=66842,["name"]="Call of the Elements",["icon"]="Interface\\Icons\\Spell_Shaman_Dropall_01",["condition"]="Place down your totems with Call of the Elements (group-dependent);"},{["spellID"]=16166,["name"]="Elemental Mastery",["icon"]="Interface\\Icons\\Spell_Nature_WispHeal",["condition"]="Elemental Mastery when available if you will be able to cast uninterrupted for its duration;"},{["spellID"]=49233,["name"]="Flame Shock",["icon"]="Interface\\Icons\\Spell_Fire_FlameShock",["condition"]="Flame Shock;"},{["spellID"]=60043,["name"]="Lava Burst",["icon"]="Interface\\Icons\\Spell_Shaman_LavaBurst",["condition"]="Lava Burst if Flame Shock will be on target when the cast finishes (no guaranteed crit if Flame Shock is only applied during Lava Burst flight time);"},{["spellID"]=49271,["name"]="Chain Lightning",["icon"]="Interface\\Icons\\Spell_Nature_ChainLightning",["condition"]="Chain Lightning if not having Mana issues;"},{["spellID"]=15207,["name"]="Lightning Bolt",["icon"]="Interface\\Icons\\Spell_Nature_Lightning",["condition"]="Lightning Bolt;"},{["spellID"]=49236,["name"]="Frost Shock",["icon"]="Interface\\Icons\\Spell_Frost_FrostShock",["condition"]="Frost Shock when movement is required and Flame Shock is already on target."}}}},["pvp"]={["overview"]={["ruRU"]={"Заклинатель, сочетающий урон, поддержку и лечение.","Опасные окна урона и полезные тотемы.","Зависимость от чтения делает прерывания особенно опасными."},["enUS"]={"Elemental Shamans are one of the top casters in Wrath PvP and have a very complete kit with tools for every situation. Their main weakness is being trained down by melee cleaves, but the new Thunderstorm and Storm, Earth and Fire talents provide control against","",""}},["rotation"]={["ruRU"]="Готовьте безопасное чтение ложными кастами, контролем и позицией. Чередуйте урон с очищением и помощью лечением; при необходимости используйте окно для питья, а не продолжайте безрезультатное давление.",["enUS"]="Rather than a fixed rotation, Elemental Shaman gameplay is about treading a fine balance between casting damage spells, utility spells, healing, and even drinking, if given the chance. Here are some basic pointers: Keep yourself alive and away from enemy melee with Thunderstorm, Earthbind Totem (Storm, Earth and Fire), Ghost Wolf and Frost Shock; Pressure enemies with Lava Burst and Chain Lightning, potentially empowered by Elemental Mastery and quickly followed up with Frost Shock. Purge, Bloodlust, and Hex are also important pressure tools which you should use in coordination with your team; Against casters and enemy healers, look for opportunities to Grounding Totem and Wind Shear their important casts; Keep an eye on your Mana pool, as it is possible to lose due to running out of Mana. You can try to drink if enemies are trying to hide away"},["builds"]={{["key"]="pvp_0",["title"]="Elemental Shaman Standard PvP Talents (60/11/0)",["talentsString"]="0533051503213051322331351-023212001-",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=563,["rank"]=5,["spellID"]=16108,["tree"]=1,["minLevel"]=10,["maxRank"]=5,["name"]="Concussion",["nameRu"]="Concussion"},{["talentID"]=561,["rank"]=3,["spellID"]=16161,["tree"]=1,["minLevel"]=15,["maxRank"]=3,["name"]="Call of Flame",["nameRu"]="Call of Flame"},{["talentID"]=1640,["rank"]=3,["spellID"]=28998,["tree"]=1,["minLevel"]=15,["maxRank"]=3,["name"]="Elemental Warding",["nameRu"]="Elemental Warding"},{["talentID"]=575,["rank"]=5,["spellID"]=16116,["tree"]=1,["minLevel"]=20,["maxRank"]=5,["name"]="Reverberation",["nameRu"]="Reverberation"},{["talentID"]=574,["rank"]=1,["spellID"]=16164,["tree"]=1,["minLevel"]=20,["maxRank"]=1,["name"]="Elemental Focus",["nameRu"]="Elemental Focus"},{["talentID"]=565,["rank"]=5,["spellID"]=60188,["tree"]=1,["minLevel"]=20,["maxRank"]=5,["name"]="Elemental Fury",["nameRu"]="Elemental Fury"},{["talentID"]=1642,["rank"]=3,["spellID"]=29065,["tree"]=1,["minLevel"]=25,["maxRank"]=3,["