,{["itemID"]=45778,["spellID"]=63298,["category"]="major",["icon"]="Interface\\Icons\\INV_Glyph_MajorShaman",["classToken"]="SHAMAN",["minLevel"]=15,["name"]="Glyph of Stoneclaw Totem",["nameRu"]="Glyph of Stoneclaw Totem"},{["itemID"]=45771,["spellID"]=63271,["category"]="major",["icon"]="Interface\\Icons\\INV_Glyph_MajorShaman",["classToken"]="SHAMAN",["minLevel"]=60,["name"]="Glyph of Feral Spirit",["nameRu"]="Glyph of Feral Spirit"},{["itemID"]=43386,["spellID"]=58063,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorShaman",["classToken"]="SHAMAN",["minLevel"]=20,["name"]="Glyph of Water Shield",["nameRu"]="Glyph of Water Shield"},{["itemID"]=43725,["spellID"]=59289,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorShaman",["classToken"]="SHAMAN",["minLevel"]=16,["name"]="Glyph of Ghost Wolf",["nameRu"]="Glyph of Ghost Wolf"},{["itemID"]=43388,["spellID"]=58057,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorShaman",["classToken"]="SHAMAN",["minLevel"]=28,["name"]="Glyph of Water Walking",["nameRu"]="Glyph of Water Walking"}},["glyphIssues"]={},["trees"]={"Elemental","Enhancement","Restoration"},["source"]="https://www.icy-veins.com/wotlk-classic/enhancement-shaman-pvp-guide",["calculator"]="https://www.icy-veins.com/wotlk-classic/shaman-talent-calculator#tc-qqrrrtttttuuxwwwzzzzzCDDDFFFGGEEEIJMMKKKONNNQQQQQR111114443336PP55555HL|0h1i3o4j5q2C"}},["sources"]={{["url"]="https://www.icy-veins.com/wotlk-classic/enhancement-shaman-pvp-guide",["sha256"]="cbf1dea795393980c793326ad2d6229fb974fb182d2e361f972c4c44d6512a7b",["date"]="2026-10-19"}},["rotationDiagram"]={["kind"]="pvp",["steps"]={{["spellID"]=8012,["name"]="Purge",["icon"]="Interface\\Icons\\Spell_Nature_Purge",["conditionRu"]="Снимите важное усиление цели.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=51533,["name"]="Feral Spirit",["icon"]="Interface\\Icons\\Spell_Shaman_FeralSpirit",["conditionRu"]="Окно давления и поддержки.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=15207,["name"]="Lightning Bolt",["icon"]="Interface\\Icons\\Spell_Nature_Lightning",["conditionRu"]="Мгновенно при пяти зарядах «Оружия Водоворота»; при необходимости лечите.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=57994,["name"]="Wind Shear",["icon"]="Interface\\Icons\\Spell_Nature_Cyclone",["conditionRu"]="Сохраните прерывание под важное чтение.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."}}}}},["SHAMAN:Restoration"]={["classToken"]="SHAMAN",["sourceSpec"]="Restoration",["role"]="healer",["pve"]={["overview"]={["ruRU"]={"Лекарь с цепным исцелением и поддержкой тотемами.","Лечение группы, полезные усиления и очищение.","Низкая мобильность; в PvP опасны прерывания."},["enUS"]={"Restoration Shaman is an excellent support with their buff totems, such as Windfury Totem, Wrath of Air Totem, and Strength of Earth Totem, as well as their utility totems such as Tremor Totem and Cleansing Totem, and support spells such as Purge, Wind Shear, and","Totems and support spells for every type of situation, from buffs to CC removal; Shared gear with Elemental allows for easy swapping between healing and damage between encounters; Great area healing with Chain Heal which ties into single healing through","Vulnerable to interrupts in PvP; Low mobility, survivability, and no defensive cooldown; Jack of all trades of healing, but master of none means raid spot is contested."}},["rotation"]={["ruRU"]="Держите щит земли на назначенном танке, водный щит — на себе. Быстрина помогает реагировать и усиливает дальнейшее лечение. Цепное исцеление — по группе, волны исцеления — по отдельной цели; очищайте опасные эффекты.",["enUS"]="Our recommendations assume you are running one of the recommended talent builds from the talents page and are playing a max level character. If you are still leveling, please refer to the leveling page for a leveling-specific rotation. Healers do not have a formal rotation. As such we will display a priority list, instead. Use Nature's Swiftness, Tidal Force, and Healing Wave as an emergency heal for players about to die; Use Lesser Healing Wave for emergency healing if Nature's Swiftness is on cooldown; Remove dangerous debuffs from group members as soon as possible. This includes preparing for Fear effects with Tremor Totem; Keep Earth Shield on the tank and Water Shield on yourself at all times; Keep your Totems active and in range of the raid at all times; Use Riptide when available; Use Chain Heal to heal group"},["builds"]={{["key"]="pve_0",["title"]="Restoration Shaman Standard PvE Talent Build (0/13/58)",["talentsString"]="-3020503-50005331335310501122331251",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=610,["rank"]=3,["spellID"]=52456,["tree"]=2,["minLevel"]=10,["maxRank"]=3,["name"]="Enhancing Totems",["nameRu"]="Enhancing Totems"},{["talentID"]=614,["rank"]=2,["spellID"]=17486,["tree"]=2,["minLevel"]=10,["maxRank"]=5,["name"]="Ancestral Knowledge",["nameRu"]="Ancestral Knowledge"},{["talentID"]=613,["rank"]=5,["spellID"]=16305,["tree"]=2,["minLevel"]=15,["maxRank"]=5,["name"]="Thundering Strikes",["nameRu"]="Thundering Strikes"},{["talentID"]=607,["rank"]=3,["spellID"]=51881,["tree"]=2,["minLevel"]=15,["maxRank"]=3,["name"]="Improved Shields",["nameRu"]="Improved Shields"},{["talentID"]=586,["rank"]=5,["spellID"]=16229,["tree"]=3,["minLevel"]=10,["maxRank"]=5,["name"]="Improved Healing Wave",["nameRu"]="Improved Healing Wave"},{["talentID"]=593,["rank"]=5,["spellID"]=16217,["tree"]=3,["minLevel"]=15,["maxRank"]=5,["name"]="Tidal Focus",["nameRu"]="Tidal Focus"},{["talentID"]=583,["rank"]=3,["spellID"]=16198,["tree"]=3,["minLevel"]=20,["maxRank"]=3,["name"]="Improved Water Shield",["nameRu"]="Improved Wate