,"Enhancement","Restoration"},["source"]="https://www.icy-veins.com/wotlk-classic/restoration-shaman-healer-pve-spec-builds-talents-glyphs",["calculator"]="https://www.icy-veins.com/wotlk-classic/shaman-talent-calculator#tc-ppprrtttttvvvSSSSSWWWWWYXYYXXZ---..._____[~~~(((((%EF%BD%A6%EF%BD%A7%EF%BD%A9%EF%BD%A9%EF%BD%AA%EF%BD%AA%EF%BD%AA%EF%BD%A8%EF%BD%A8%EF%BD%AB%EF%BD%AB%EF%BD%AB%EF%BD%AC%EF%BD%AE%EF%BD%AE%EF%BD%AE%EF%BD%AE%EF%BD%AE%EF%BD%AF%EF%BD%AD%EF%BD%AD|0z1w3t4o5q2s"}},["sources"]={{["url"]="https://www.icy-veins.com/wotlk-classic/restoration-shaman-healer-pve-guide",["sha256"]="0778c199e80936318ac2e195f4ae10a6dfa284ca39731bb672c4bbd9997a30f5",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/restoration-shaman-healer-pve-spec-builds-talents-glyphs",["sha256"]="fd8500f5d8244a7b5fd051ec8c412867667956f3de79051b45b6a05558342810",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/restoration-shaman-healer-pve-rotation-cooldowns-abilities",["sha256"]="3ae94c6ba9c872600fbc3aacf7fec022cfa3323b7896c2689a159ec3962923c1",["date"]="2026-10-19"}},["rotationDiagram"]={["kind"]="priority",["heading"]="Spell Priority for Restoration Shamans",["steps"]={{["spellID"]=16188,["name"]="Nature's Swiftness",["icon"]="Interface\\Icons\\Spell_Nature_RavenForm",["condition"]="Use Nature's Swiftness, Tidal Force, and Healing Wave as an emergency heal for players about to die;"},{["spellID"]=49276,["name"]="Lesser Healing Wave",["icon"]="Interface\\Icons\\Spell_Nature_HealingWaveLesser",["condition"]="Use Lesser Healing Wave for emergency healing if Nature's Swiftness is on cooldown;"},{["spellID"]=8143,["name"]="Tremor Totem",["icon"]="Interface\\Icons\\Spell_Nature_TremorTotem",["condition"]="Remove dangerous debuffs from group members as soon as possible. This includes preparing for Fear effects with Tremor Totem;"},{["spellID"]=974,["name"]="Earth Shield",["icon"]="Interface\\Icons\\Spell_Nature_SkinofEarth",["condition"]="Keep Earth Shield on the tank and Water Shield on yourself at all times;"},{["spellID"]=61295,["name"]="Riptide",["icon"]="Interface\\Icons\\spell_nature_riptide",["condition"]="Use Riptide when available;"},{["spellID"]=55459,["name"]="Chain Heal",["icon"]="Interface\\Icons\\Spell_Nature_HealingWaveGreater",["condition"]="Use Chain Heal to heal group damage, consuming a Riptide buff if available and the damage warrants it for extra healing;"},{["spellID"]=10396,["name"]="Healing Wave",["icon"]="Interface\\Icons\\Spell_Nature_MagicImmunity",["condition"]="Use Healing Wave to heal single-target damage."}}}},["pvp"]={["overview"]={["ruRU"]={"Лекарь с активной поддержкой, тотемами и очищением.","Может сочетать лечение, снятие эффектов и помощь уроном.","Уязвимость к прерываниям и давление на ману."},["enUS"]={"Restoration Shamans suffer from their reliance on cast time heals in Wrath Classic's Arena. While they do get new instant healing tools in Riptide and Earthliving Weapon, on top of Earth Shield now only losing 1 stack per dispel, which makes it extremely hard to","",""}},["rotation"]={["ruRU"]="Сначала сохраняйте союзника и защитные эффекты, затем используйте очищение, контроль и безопасные окна для питья. Ложные начала чтения помогают вынудить противника потратить прерывание.",["enUS"]="Rather than a fixed rotation, Shaman gameplay is about treading a fine balance between healing, drinking, casting utility spells, and also damage spells, if given the chance. Here is the general idea: Keep yourself alive and away from enemy melee with Ghost Wolf, Earthbind Totem, and Frost Shock; Pressure enemies with Purge, Bloodlust, and Hex. If an opportunity arises, you can also try to Lava Burst and Chain Lightning to help land a kill, assuming no ally needs emergency healing and you can cast uninterrupted; Against casters and enemy healers, look for opportunities to Grounding Totem and Wind Shear their important casts; Keep an eye on your Mana pool, as it is possible to lose due to running out of Mana. You can try to drink if enemies are not actively focusing you, but that will often lead to falling"},["builds"]={{["key"]="pvp_0",["title"]="Restoration Shaman PvP Talents (0/17/54)",["talentsString"]="-023242301-50032331330313501120331251",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=2101,["rank"]=2,["spellID"]=16130,["tree"]=2,["minLevel"]=10,["maxRank"]=2,["name"]="Earth's Grasp",["nameRu"]="Earth's Grasp"},{["talentID"]=614,["rank"]=3,["spellID"]=17487,["tree"]=2,["minLevel"]=10,["maxRank"]=5,["name"]="Ancestral Knowledge",["nameRu"]="Ancestral Knowledge"},{["talentID"]=609,["rank"]=2,["spellID"]=16293,["tree"]=2,["minLevel"]=15,["maxRank"]=2,["name"]="Guardian Totems",["nameRu"]="Guardian Totems"},{["talentID"]=613,["rank"]=4,["spellID"]=16304,["tree"]=2,["minLevel"]=15,["maxRank"]=5,["name"]="Thundering Strikes",["nameRu"]="Thundering Strikes"},{["talentID"]=605,["rank"]=2,["spellID"]=16287,["tree"]=2,["minLevel"]=15,["maxRank"]=2,["name"]="Improved Ghost Wolf",["nameRu"]="Improved Ghost Wolf"},{["talentID"]=607,["rank"]=3,["spellID"]=51881,["tree"]=2,["minLevel"]=15,["maxRank"]=3,["name"]="Improved Shields",["nameRu"]="Improved Shields"},{["talentID"]=617,["rank"]=1,["spellID"]=43338,["tree"]=2,["minLevel"]=20,["maxRank"]=1,["name"]="Shamanistic Focus",["nameRu"]="Shamanistic Focus"},{["talentID"]=586,["rank"]=5,["spellID"]=16229,["tree"]=3,["minLevel"]=10,["maxRank"]=5,["name"]="Improved Healing Wave",["nameRu"]="Improved Healing Wave"},{["talentID"]=1646,["rank"]=3,["spellID"]=29191,["tree"]=3,["minLevel"]=15,["maxRank"]=3,["name"]="Healing Grace",["nameRu"]="Healing Grace"},{["talentID"]=593,["rank"]=2,["spellID"]=16214,["tree"]=3,["minLevel"]=15,["maxRank"]=5,["name"]="Tidal Focus",["nameRu"]="Tidal Focus"},{["talentID"]=583,["rank"]=3,["spellID"]=16198,["tree"]=3,["minLevel"]=20,["maxRank"]=3,["name"]="Improved Water Shield",["nameRu"]="Improved Water Shield"},{["talentID"]=587,["rank"]=3,["spellID"]=16232,["tree"]=3,["m