n"]="Interface\\Icons\\INV_Glyph_MinorWarlock",["classToken"]="WARLOCK",["minLevel"]=15,["name"]="Glyph of Unending Breath",["nameRu"]="Glyph of Unending Breath"}},["glyphIssues"]={},["trees"]={"Affliction","Demonology","Destruction"},["source"]="https://www.icy-veins.com/wotlk-classic/affliction-warlock-pvp-guide",["calculator"]="https://www.icy-veins.com/wotlk-classic/warlock-talent-calculator#tc-1112222266988877bbcccedahhhhhiiijjjjmmmlljopqqqqqrvvuuuyyyABCCCEafwwETT|0j1a2H3G4c5l"}},["sources"]={{["url"]="https://www.icy-veins.com/wotlk-classic/affliction-warlock-pvp-guide",["sha256"]="8e3440c37c021bba58c415570bde2592f981bca632f77d6d5a63cabc1abc48c9",["date"]="2026-10-19"}},["rotationDiagram"]={["kind"]="pvp",["steps"]={{["spellID"]=30108,["name"]="Unstable Affliction",["icon"]="Interface\\Icons\\Spell_Shadow_UnstableAffliction_3",["conditionRu"]="Периодическое давление и наказание за снятие.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=47812,["name"]="Corruption",["icon"]="Interface\\Icons\\Spell_Shadow_AbominationExplosion",["conditionRu"]="Поддерживайте на доступных целях без контроля.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=48181,["name"]="Haunt",["icon"]="Interface\\Icons\\Ability_Warlock_Haunt",["conditionRu"]="Усиливайте давление по основной цели.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=6215,["name"]="Fear",["icon"]="Interface\\Icons\\Spell_Shadow_Possession",["conditionRu"]="Контроль или защита; учитывайте убывание эффективности.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."}}}}},["WARLOCK:Demonology"]={["classToken"]="WARLOCK",["sourceSpec"]="Demonology",["role"]="ranged",["pve"]={["overview"]={["ruRU"]={"Заклинатель с усиленным демоном и метаморфозой.","Демонический союз усиливает группу; мощные окна массового урона.","Смерть питомца дорого обходится; длительный урон уступает колдовству."},["enUS"]={"Demonology Warlock, unlike previous expansions, is not only one of the coolest looking specs in the game, but also extremely powerful. No other class compares to their AoE, and their single-target is right up there with the best of them.","Brings the extremely powerful Demonic Pact buff to the raid. Demonology typically gets funneled gear to buff the raid more. Strong burst and AoE during Metamorphosis.","Weaker single-target DPS than Affliction. You lose a lot of damage if your pet dies. Pet AI can have issues on some fights. Typically only one Demo Lock in the Raid."}},["rotation"]={["ruRU"]="Держите питомца в бою и поддерживайте нужные эффекты. В метаморфозе используйте её способности безопасно; стрела тьмы заполняет паузы. Проки огненных недр и истребления меняют приоритет, в добивании важен ожог души.",["enUS"]="Demonology Warlock's rotation is one of the most fun and engaging rotations in the game. It is easy to play, but also has enough nuances in it to keep you engaged the entire time largely thanks to Decimation, which allow Demonology Warlocks to have an execute ability once the target gets to 35% health. This page will go over the single-target rotation, as well as the AoE and execute rotation. Your opener as Demonology matters a lot in terms of both damage and supporting with your the opening Demonic Pact. That first Demonic Pact is important because this is typically when the raid uses their big damage abilities and cooldowns. This is also when most guilds Bloodlust, so it is nice to have a big Demonic Pact on the raid during this time. Do not start at max range. You"},["builds"]={{["key"]="pve_0",["title"]="Talent Builds for Warlock in Wrath of the Lich King (2/54/15)",["talentsString"]="02-003203301135202530135201351-55000005",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=1005,["rank"]=2,["spellID