of Felguard"},{["itemID"]=43390,["spellID"]=58070,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorWarlock",["classToken"]="WARLOCK",["minLevel"]=15,["name"]="Glyph of Drain Soul",["nameRu"]="Glyph of Drain Soul"},{["itemID"]=43389,["spellID"]=58079,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorWarlock",["classToken"]="WARLOCK",["minLevel"]=15,["name"]="Glyph of Unending Breath",["nameRu"]="Glyph of Unending Breath"},{["itemID"]=43394,["spellID"]=58094,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorWarlock",["classToken"]="WARLOCK",["minLevel"]=68,["name"]="Glyph of Souls",["nameRu"]="Glyph of Souls"}},["glyphIssues"]={},["trees"]={"Affliction","Demonology","Destruction"},["source"]="https://www.icy-veins.com/wotlk-classic/demonology-warlock-dps-pve-spec-builds-talents-glyphs",["calculator"]="https://www.icy-veins.com/wotlk-classic/warlock-talent-calculator#tc-TTTTTUUUUU-----11vvuuuyyyxxxBACCCEEDDDDDGGHHHHHIIIKLLLNNMMMMMPQQQRRRRRS|0i1j2A3c4l5F"}},["sources"]={{["url"]="https://www.icy-veins.com/wotlk-classic/demonology-warlock-dps-pve-guide",["sha256"]="7b91d59c29a579af206e3ba2ee92f8d0798a1f5d84379a423f1a1cfe19a3ef03",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/demonology-warlock-dps-pve-spec-builds-talents-glyphs",["sha256"]="cd5e6117738d6995a3f4f017ee0231f39bab821e1dd0957c7a544341c23a3959",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/demonology-warlock-dps-pve-rotation-cooldowns-abilities",["sha256"]="85ba85bfe3d2db79bd50d4c00488035abaabc41fa9a05397b0c99bd28be1a802",["date"]="2026-10-19"}}}},["WARLOCK:Destruction"]={["classToken"]="WARLOCK",["sourceSpec"]="Destruction",["role"]="ranged",["pve"]={["overview"]={["ruRU"]={"Заклинатель огня с взрывным уроном и контролем.","Предсказуемые окна урона, восполнение маны и неистовство тьмы.","В рейдовом уроне уступает другим вариантам чернокнижника; нет сильного добивания."},["enUS"]={"Destruction Warlock, as they have always been, is focused on hard casting powerful abilities into your enemies. This spec uses Fire spells and Summon Imp, allowing us to shoot our Firebolts faster and harder than ever. Destruction's sole purpose is to do as much damage","Brings Replenishment to the raid Solid burst damage and sustain. Shadowfury helps with add control","The weakest of the 3 Warlock specializations. Lower single-target than Affliction Lower AoE than Demonology No execute ability"}},["rotation"]={["ruRU"]="Держите жертвенный огонь и подходящее проклятие. Поджигание и стрела хаоса используются по готовности; испепеление заполняет паузы. На большой группе применяйте семя порчи и следите за угрозой.",["enUS"]="Destruction Warlock's rotation is one of the most fun and engaging rotations in the game. It is easy to play, but also has enough nuances in it to keep you engaged the entire time, largely thanks to the synergy between Conflagrate and Backdraft. Pre-Pot a potion — I suggest a Potion of Wild Magic for your prepop, largely because most guilds Bloodlust at the start of encounters and if you were to instead use a Potion of Speed there is a chance with your Backdraft charges that you will be casting under the global cooldown. If your guild is not lusting at the start and you do not have this issue, then feel free to use a Potion of Speed. Precast Soul Fire so that it lands on the boss right as the pull timer hits zero. A good way"},["builds"]={{["key"]="pve_0",["title"]="Talent Builds for Destruction Warlock in Wrath of the Lich King (0/19/52)",["talentsString"]="-033100301134-05203205210231051035030351",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=1222,["rank"]=3,["spellID"]=18696,["tree"]=2,["minLevel"]=10,["maxRank"]=3,["name"]="Improved Imp",["nameRu"]="Improved Imp"},{["talentID"]=1223,["rank"]=3,["spellID"]=18699,["tree"]=2,["minLevel"]=10,["maxRank"]=3,["name"]="Demonic Embrace",["nameRu"]="Demonic Embrace"},{["talentID"]=1883,["rank"]=1,["spellID"]=47230,["tr