rlock",["classToken"]="WARLOCK",["minLevel"]=15,["name"]="Glyph of Drain Soul",["nameRu"]="Glyph of Drain Soul"},{["itemID"]=43389,["spellID"]=58079,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorWarlock",["classToken"]="WARLOCK",["minLevel"]=15,["name"]="Glyph of Unending Breath",["nameRu"]="Glyph of Unending Breath"},{["itemID"]=43394,["spellID"]=58094,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorWarlock",["classToken"]="WARLOCK",["minLevel"]=68,["name"]="Glyph of Souls",["nameRu"]="Glyph of Souls"}},["glyphIssues"]={},["trees"]={"Affliction","Demonology","Destruction"},["source"]="https://www.icy-veins.com/wotlk-classic/destruction-warlock-dps-pve-spec-builds-talents-glyphs",["calculator"]="https://www.icy-veins.com/wotlk-classic/warlock-talent-calculator#tc-tttuuuvyyyCCCBAUUUUUXXXVV-----YY.._[[]]](%EF%BD%A6%EF%BD%A6%EF%BD%A6%EF%BD%A6%EF%BD%A6%EF%BD%A9%EF%BD%A9%EF%BD%A9%EF%BD%A7%EF%BD%AA%EF%BD%AA%EF%BD%AA%EF%BD%AA%EF%BD%AA%EF%BD%AC%EF%BD%AC%EF%BD%AC%EF%BD%AE%EF%BD%AE%EF%BD%AE%EF%BD%AF%EF%BD%AF%EF%BD%AF%EF%BD%AF%EF%BD%AF%EF%BD%B0DDDD|0h1i2x3c4l5F"}},["sources"]={{["url"]="https://www.icy-veins.com/wotlk-classic/destruction-warlock-dps-pve-guide",["sha256"]="5352ec8faaa5a4c1f20e97173773c068e2d15c6f0d325e7bcf09066dbb46682f",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/destruction-warlock-dps-pve-spec-builds-talents-glyphs",["sha256"]="06b0a1b9a5466f711504441c7f7680a337a236be6421ddda1bbfd1bc8640d8ef",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/destruction-warlock-dps-pve-rotation-cooldowns-abilities",["sha256"]="fa08d25df90dd56a0608aff4e1ac75f81409b10cc255b2a6c725a40f27a0901b",["date"]="2026-10-19"}}},["pvp"]={["overview"]={["ruRU"]={"Заклинатель короткого взрывного урона в подготовленную цель.","Контроль команды противника позволяет безопасно завершить серию.","Много читаемых заклинаний; без окна контроля противник легко отвечает."},["enUS"]={"Destruction Warlock differs from Affliction Warlock greatly. Instead of focusing on spread pressure, Destruction Warlocks aim to crowd control the enemy team and burst down one target quickly in a short window. Destruction Warlocks hard cast a lot of their abilities, and pairs well with","Extremely high burst damage, can easily surprise your enemies. Very quick damage setup, can quickly swap targets if you catch someone out of place. Multiple forms of crowd control for peeling.","Relies on casting most spells for damage. Hard time dealing with line of site and high mobility targets. Damage is very telegraphed who and when you are bursting."}},["rotation"]={["ruRU"]="Сначала создавайте возможность читать: оглушение или страх по лекарю, затем атака назначенной цели. Согласуйте контроль и урон с напарником; не тратьте главное окно в свободно действующего лекаря.",["enUS"]="As a Destruction Warlock it is important to prioritise the correct stats in order to perform in Wrath of the Lich King PvP. Below, we go over relevant stats that you should aim for. Destruction Warlocks playstyle should focus on creating as many windows to free cast damage as possible. For example, asting Shadowfury into a Fear on an enemy healer, and then casting damage into your target is much more effective than dealing damage while the healer is not in Crowd Control. Cast Fear on a target. Cast Immolate on your kill target. Cast Conflagrate to gain Backdraft stacks. Cast Shadowfury on your target. Cast Chaos Bolt. Cast Incinerate. Cast Shadowburn as an execute. It is worth applying Corruption to protect your Immolate and Fear from being dispelled or when you need to move."},["builds"]={{["key"]="pvp_0",["title"]="General PvP Talent Build (0/17/54)",["talentsString"]="-0032203011302-45230015220231251015031051",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=1223,["rank"]=3,["spellID"]=18699,["tree"]=2,["minLevel"]=10,["maxRank"]=3,["name"]="Demonic Embrace",["nameRu"]="Demonic Embrace"},{["talentID"]=1883,["rank"]=2,["spellID"]=47231,["tree"]=2,["minLevel"]=10,["maxRank"]=2,["name"]="Fel Synergy",["nameRu"]="Fel Synergy"},{["talentID"]=1224,["rank"]=2,["spellID"]=18704,["tree"]=2,["minLevel"]=15,["maxRank"]=2,["name"]="Improved Health Funnel",["nameRu"]="Improved Health Funnel"},{["talentID"]=1242,["rank"]=3,["spellID"]=18744,["tree"]=2,["minLevel"]=15,["maxRank"]=3,["name"]="Fel Vitality",["nameRu"]="Fel Vitality"},{["talentID"]=1282,["rank"]=1,["spellID"]=19028,["tree"]=2,["minLevel"]=20,["maxRank"]=1,["name"]="Soul Link",["nameRu"]="Soul Link"},{["talentID"]=1226,["rank"]=1,["spellID"]=18708,["tree"]=2,["minLevel"]=20,["maxRank"]=1,["name"]="Fel Domination",["nameRu"]="Fel Domination"},{["talentID"]=1671,["rank"]=3,["spellID"]=30145,["tree"]=2,["minLevel"]=20,["maxRank"]=3,["name"]="Demonic Aegis",["nameRu"]="Demonic Aegis"},{["talentID"]=1227,["rank"]=2,["spellID"]=18710,["tree"]=2,["minLevel"]=25,["maxRank"]=2,["name"]="Master Summoner",["nameRu"]="Master Summoner"},{["talentID"]=944,["rank"]=4,["spellID"]=17802,["tree"]=3,["minLevel"]=10,["maxRank"]=5,["name"]="Improved Shadow Bolt",["nameRu"]="Improved Shadow Bolt"},{["talentID"]=943,["rank"]=5,["spellID"]=17792,["tree"]=3,["minLevel"]=10,["maxRank"]=5,["name"]="Bane",["nameRu"]="Bane"},{["talentID"]=982,["rank"]=2,["spellID"]=18120,["tree"]=3,["minLevel"]=15,["maxRank"]=2,["name"]="Aftermath",["nameRu"]="Aftermath"},{["talentID"]=1887,["rank"]=3,["spellID"]=63351,["tree"]=3,["minLevel"]=15,["maxRank"]=3,["name"]="Molten Skin",["nameRu"]="Molten Skin"},{["talentID"]=963,["rank"]=1,["spellID"]=17877,["tree"]=3,["minLevel"]=20,["maxRank"]=1,["name"]="Shadowburn",["nameRu"]="Shadowburn"},{["talentID"]=967,["rank"]=5,["spellID"]=59741,["tree"]=3,["minLevel"]=20,["maxRank"]=5,["name"]="Ruin",["nameRu"]="Ruin"},{["talentID"]=985,["rank"]=2,["spellID"]=18136,["tree"]=3,["minLevel"]=25,["maxRank"]=2,["name"]="Intensity",["nameRu"]="Intensity"},{["talentID"]=964,["rank"]=2,["spellID"]=17918,["tree"]=3,["minLevel"]=25,["maxRa