["spellID"]=58070,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorWarlock",["classToken"]="WARLOCK",["minLevel"]=15,["name"]="Glyph of Drain Soul",["nameRu"]="Glyph of Drain Soul"},{["itemID"]=43389,["spellID"]=58079,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorWarlock",["classToken"]="WARLOCK",["minLevel"]=15,["name"]="Glyph of Unending Breath",["nameRu"]="Glyph of Unending Breath"}},["glyphIssues"]={"Glyph of Subjugate Demon"},["trees"]={"Affliction","Demonology","Destruction"},["source"]="https://www.icy-veins.com/wotlk-classic/destruction-warlock-pvp-guide",["calculator"]="https://www.icy-veins.com/wotlk-classic/warlock-talent-calculator#tc-UUUUUVVWWW-----Z__..(]]][[))%EF%BD%A6%EF%BD%A6%EF%BD%A6%EF%BD%A6%EF%BD%A6%EF%BD%A7%EF%BD%AA%EF%BD%AA%EF%BD%AA%EF%BD%AA%EF%BD%AA%EF%BD%AD%EF%BD%AC%EF%BD%AC%EF%BD%AC%EF%BD%AF%EF%BD%AF%EF%BD%AF%EF%BD%AF%EF%BD%AF%EF%BD%B0vvuuuyyywwABCCCEE)[zzz|0s1H2x3c4l5w"}},["sources"]={{["url"]="https://www.icy-veins.com/wotlk-classic/destruction-warlock-pvp-guide",["sha256"]="60c4268cb35845ae5b8f338d51fd280b66c7d256776752c9f0b3c9880ab7e75e",["date"]="2026-10-19"}},["rotationDiagram"]={["kind"]="pvp",["steps"]={{["spellID"]=30283,["name"]="Shadowfury",["icon"]="Interface\\Icons\\Spell_Shadow_Shadowfury",["conditionRu"]="Подготовьте безопасное окно чтения.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=27215,["name"]="Immolate",["icon"]="Interface\\Icons\\Spell_Fire_Immolation",["conditionRu"]="Подготовка урона и поджигания.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=17962,["name"]="Conflagrate",["icon"]="Interface\\Icons\\Spell_Fire_Fireball",["conditionRu"]="Требуется нужный периодический эффект.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=50796,["name"]="Chaos Bolt",["icon"]="Interface\\Icons\\Ability_Warlock_ChaosBolt",["conditionRu"]="Окно безопасного чтения по выбранной цели.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."},{["spellID"]=17877,["name"]="Shadowburn",["icon"]="Interface\\Icons\\Spell_Shadow_ScourgeBuild",["conditionRu"]="Мгновенное завершение атаки.",["condition"]="Situational ability: consider the PvP priorities above, control and defensive cooldowns."}}}}},["WARRIOR:Arms"]={["classToken"]="WARRIOR",["sourceSpec"]="Arms",["role"]="melee",["pve"]={["overview"]={["ruRU"]={"Боец ближнего боя с двуручным оружием, кровотечением и проками.","Полезные ослабления и урон по нескольким близким целям.","В поздней экипировке масштабируется слабее неистовства."},["enUS"]={"Arms Warrior has received some great changes in Wrath of the Lich King, giving the spec its own, unique playstyle that makes it stand out. Arms Warrior excels in multi-target scenarios, being one of the highest sustained cleave damage dealers out there.","Brings multiple debuffs with Trauma and Blood Frenzy. High damage against 3-4 targets with consistent cleave. Not reliant on resources; can sustain combat infinitely.","Does not scale well; becomes redundant in later tiers. Brings no utility to the raid, only damage. High incentive to use either Axes or Polearms, reducing the amount of available weapons."}},["rotation"]={["ruRU"]="Поддерживайте кровопускание; расходуйте проки превосходства и внезапной смерти, не теряя их. Смертельный удар и мощный удар заполняют приоритет. Вихрь клинков и размашистые удары планируйте под несколько целей и усиления.",["enUS"]="The Arms Warrior rotation is very active, having multiple procs that activate different abilities for us. Arms Warrior relies on managing all of your different procs and keeping your Rend applied. You will spend your entire time as an Arms Warrior in Battle Stance, unlike other Warrior builds. Sunder Armor — Sunder Armor remains your best opening ability on bosses, increasing all Physical damage taken. You do not need to do this if someone else, such as a Rogue, is applying an Armor reduction debuff. Rend — You must always maintain an active Rend on a target to get Taste for Blood procs, allowing you to use Overpower. Overpower — Be sure to use Overpower as often as possible to prevent a Taste for Blood proc from going to waste. Bladestorm — This is your next priority as it deals"},["builds"]={{["key"]="pve_0",["title"]="Talent Builds for Arms Warrior in Wrath of the Lich King (55/8/8)",["talentsString"]="3022032023335100102012213231251-305-2033",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=124,["rank"]=3,["spellID"]=12664,["tree"]=1,["minLevel"]=10,["maxRank"]=3,["name"]="Improved Heroic Strike",["nameRu"]="Improved Heroic Strike"},{["talentID"]=127,["rank"]=2,["spellID"]=12658,["tree"]=1,["minLevel"]=10,["maxRank"]=2,["name"]="Improved Rend",["nameRu"]="Improved Rend"},{["talentID"]=126,["rank"]=2,["spellID"]=12697,["tree"]=1,["minLevel"]=15,["maxRank"]=2,["name"]="Improved Charge",["nameRu"]="Improved Charge"},{["talentID"]=128,["rank"]=3,["spellID"]=12677,["tree"]=1,["minLevel"]=15,["maxRank"]=3,["name"]="Tactical Mastery",["nameRu"]="Tactical Mastery"},{["talentID"]=131,["rank"]=2,["spellID"]=12963,["tree"]=1,["minLevel"]=20,["maxRank"]=2,["name"]="Improved Overpower",["nameRu"]="Improved Overpower"},{["talentID"]=662,["rank"]=2,["spellID"]=16494,["tree"]=1,["minLevel"]=20,["maxRank"]=2,["name"]="Impale",["nameRu"]="Impale"},{["talentID"]=121,["rank"]=3,["spellID"]=12867,["tree"]=1,["minLevel"]=20,["maxRank"]=3,["name"]="Deep Wounds",["nameRu"]="Deep Wounds"},{["talentID"]=136,["rank"]=3,["spellID"]=12712,["tree"]=1,["minLevel"]=25,["maxRank"]=3,["name"]="Two-Handed Weapon Specialization",["nameRu"]="Two-Handed Weapon Specialization"},{["talentID"]=2232,["rank"]=3,["spellID"]=56638,["tree"]=1,["minLevel"]=25,["maxRank"]=3,["name"]="Taste for Blood",["nameRu"]="Taste for Blood"},{["talentID"]=132,[