ategory"]="major",["icon"]="Interface\\Icons\\INV_Glyph_MajorWarrior",["classToken"]="WARRIOR",["minLevel"]=36,["name"]="Glyph of Whirlwind",["nameRu"]="Glyph of Whirlwind"},{["itemID"]=43418,["spellID"]=58357,["category"]="major",["icon"]="Interface\\Icons\\INV_Glyph_MajorWarrior",["classToken"]="WARRIOR",["minLevel"]=15,["name"]="Glyph of Heroic Strike",["nameRu"]="Glyph of Heroic Strike"},{["itemID"]=43423,["spellID"]=58385,["category"]="major",["icon"]="Interface\\Icons\\INV_Glyph_MajorWarrior",["classToken"]="WARRIOR",["minLevel"]=15,["name"]="Glyph of Rending",["nameRu"]="Glyph of Rending"},{["itemID"]=43399,["spellID"]=58098,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorWarrior",["classToken"]="WARRIOR",["minLevel"]=15,["name"]="Glyph of Thunder Clap",["nameRu"]="Glyph of Thunder Clap"},{["itemID"]=49084,["spellID"]=68164,["category"]="minor",["icon"]="Interface\\Icons\\INV_Glyph_MinorWarrior",["classToken"]="WARRIOR",["minLevel"]=68,["name"]="Glyph of Command",["nameRu"]="Glyph of Command"}},["glyphIssues"]={"Glyph of Shattering Throw"},["trees"]={"Arms","Fury","Protection"},["source"]="https://www.icy-veins.com/wotlk-classic/fury-warrior-dps-pve-spec-builds-talents-glyphs",["calculator"]="https://www.icy-veins.com/wotlk-classic/warrior-talent-calculator#tc-000225554488999aaaxxxxxwwvvvDDDDDEEEEEHHHIALLLLLNMMMOOQQQQQSTTTUUUUUV6b|0v1e2h3m4F5I"}},["sources"]={{["url"]="https://www.icy-veins.com/wotlk-classic/fury-warrior-dps-pve-guide",["sha256"]="f951638980f6861fba21101c3390b99abd3a985c151180b98e55d5cd2f602bdd",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/fury-warrior-dps-pve-spec-builds-talents-glyphs",["sha256"]="f07ddffc1866405b2c7359b80857983abea59c16fd6f855b8f24856f03f52f38",["date"]="2026-10-19"},{["url"]="https://www.icy-veins.com/wotlk-classic/fury-warrior-dps-pve-rotation-cooldowns-abilities",["sha256"]="4f7c68adb01701c289d63d0abd830ae21580d9e3269dbe0148c88b9a03d5ab89",["date"]="2026-10-19"}},["rotationDiagram"]={["kind"]="priority",["heading"]="Fury Warrior Single-Target Damage Rotation in Wrath of the Lich King",["steps"]={{["spellID"]=7386,["name"]="Sunder Armor",["icon"]="Interface\\Icons\\Ability_Warrior_Sunder",["condition"]="Sunder Armor — Sunder Armor remains your best opening ability on bosses, increasing all Physical damage taken. You do not need to do this if someone else, such as a Rogue, is applying an Expose Armor."},{["spellID"]=47475,["name"]="Slam",["icon"]="Interface\\Icons\\Ability_Warrior_DecisiveStrike",["condition"]="Slam — You will want to use Slam as quicly as possible whenever you get a Bloodsurge proc. Be aware of your buffs and do not use Slam without a Bloodsurge proc as it will not be instant cast and will pause your melee swing timer."},{["spellID"]=23881,["name"]="Bloodthirst",["icon"]="Interface\\Icons\\Spell_Nature_BloodLust",["condition"]="Bloodthirst — This spell is the bread and butter of a Fury Warrior's rotation. It has a very low cooldown, letting you use it constantly. Make sure to use this ability as much as possible. It also has a 20% chance to proc Bloodsurge."},{["spellID"]=1680,["name"]="Whirlwind",["icon"]="Interface\\Icons\\Ability_Whirlwind",["condition"]="Whirlwind — Whirlwind is your highest damage-dealing ability due to you wielding 2 two-handed weapons along with the talent Improved Whirlwind. It also has a 20% chance to proc Bloodsurge."},{["spellID"]=46845,["name"]="Rend",["icon"]="Interface\\Icons\\Ability_Gouge",["condition"]="Rend — With Improved Rend and  Glyph of Rending, using Rend while all of your other abilities are on cooldown is roughly a 100 DPS increase. Only use this if nothing else will come off cooldown within the next 1.5 seconds."},{["spellID"]=25286,["name"]="Heroic Strike",["icon"]="Interface\\Icons\\Ability_Rogue_Ambush",["condition"]="Heroic Strike — You will start using Heroic Strike when you have more than 40 Rage to prevent wasting excess Rage. Heroic Strike is a large portion of your damage dealt, so keeping it queued up constantly is a high priority for this spec."},{["spellID"]=47471,["name"]="Execute",["icon"]="Interface\\Icons\\INV_Sword_48",["condition"]="Execute — Execute has dropped from being one of your highest-priority spells to your lowest as it has been nerfed greatly in WotLK. Only use this if you have nothing else available, and enough rage to continue using Heroic Strike."}}}}},["WARRIOR:Protection"]={["classToken"]="WARRIOR",["sourceSpec"]="Protection",["role"]="tank",["pve"]={["overview"]={["ruRU"]={"Подвижный танк со щитом, блокированием и активным контролем.","Мобильность, быстрый набор угрозы, оглушения и отражение заклинаний.","Блокирование помогает не против любого урона; защиту нужно планировать."},["enUS"]={"If you would like to see where Protection Warrior falls in the overall rankings among DPS specs for both PvE and PvP in WotLK Classic, we have created pages dedicated to explaining what classes and specializations are the best of the best through multiple factors.","Very high threat and damage compared to other tanks. Extremely mobile, having multiple gap-closers. Amazing AoE tanks, having the highest initial threat. A very diverse toolkit, having multiple stuns, interrupts and unique utility such as Spell Reflection.","Most of their mitigation comes from blocking, which will not always help. No real additional defensive cooldowns gained in WotLK. Much less versatile than other tanks in terms of raid utility. Incorrect stigma about being a bad tank, making them"}},["rotation"]={["ruRU"]="Мощный удар щитом усиливается блоком щитом; без него особое значение имеет реванш. Поддерживайте необходимые ослабления. Удар грома и ударная волна помогают на группе, рассекающий удар расходует лишнюю ярость.",["enUS"]="Protection Warrior has a very simple, yet engaging rotation. Your rotation revolves around 3 key abilities; but with procs, Rage management, short cooldowns, and general tank responsibilities, Protection Warrior has a very deep and satisfying gameplay loop. Shield Slam when Shield Block is active — Thanks to Shield Block doubling your Block Value and allowing Shield Slam to bypass the Block Value cap on your Shield Slam damage, you will want to prioritize using it over Revenge in a pure single-target situation while your Shield Block is active. Revenge — Revenge is your highest-damage ability thanks to Improved Revenge, and is only slightly behind Shield Slam in terms of threat generation. Seeing as Revenge has a low Rage cost, low cooldown, hits 2 targets, and deals very high damage, you will want to use this every time it is available."},["builds"]={{["key"]="pve_0",["title"]="Deep Protection Warrior Talent Build (15/3/53)",["talentsString"]="0500230023-3-053351225000212521030113321",["targetLevel"]=80,["points"]=71,["allocations"]={{["talentID"]=130,["rank"]=5,["spellID"]=16466,["tree"]=1,["minLevel"]=10,["maxRank"]=5,["name"]="Deflection",["nameRu"]="Deflection"},{["talentID"]=641,["rank"]=2,["spellID"]=12959,["tree"]=1,["minLevel"]=15,["maxRank"]=3,["name"]="Iron Will",["nameRu"]="Iron Will"},{["talentID"]=128,["rank"]=3,["spellID"]=12677,["tree"]=1,["minLevel"]=15,["maxRank"]=3,["name"]="Tactical Mastery",["nameRu"]="Tactical Mastery"},{["talentID"]=662,["rank"]=2,["spellID"]=16494,["tree"]=1,["minLevel"]=20,["maxRank"]=2,["name"]="Impale",["nameRu"]="Impale"},{["talentID"]=121,["rank"]=3,["spellID"]=12867,["tree"]=1,["minLevel"]=20,["maxRank"]=3,["name"]="Deep Wounds",["nameRu"]="Deep Wounds"},{["talentID"]=2250,["rank"]=3,["spellID"]=61222,["tree"]=2,["minLevel"]=10,["maxRank"]=3,["name"]="Armored to the Teeth",["nameRu"]="Armored to the Teeth"},{["talentID"]=1601,["rank"]=5,["spellID"]=12727,["tree"]=3,["minLevel"]=10,["maxRank"]=5,["name"]="Shield Specialization",["nameRu"]="Shield Specialization"},{["talentID"]=141,["rank"]=3,["spellID"]=12666,["tree"]=3,["minLevel"]=10,["maxRank"]=3,["name"]="Improved Thunder Clap",["nameRu"]="Improved Thunder Clap"},{["talentID"]=144,["