["url"]="https://www.icy-veins.com/wotlk-classic/fire-mage-dps-pve-rotation-cooldowns-abilities",["sha256"]="7df8046281a844680c79973b3a128cba1e1b5da583af837f1081849ab4af1f27",["date"]="2026-10-19"}},["rotationDiagram"]={["kind"]="priority",["steps"]={{["spellID"]=55360,["name"]="Living Bomb",["icon"]="Interface\\Icons\\Ability_Mage_LivingBomb",["condition"]="Refresh after the bomb explodes.",["conditionRu"]="Обновляйте после взрыва бомбы."},{["spellID"]=42859,["name"]="Scorch",["icon"]="Interface\\Icons\\Spell_Fire_SoulBurn",["condition"]="Only if the raid needs Improved Scorch.",["conditionRu"]="Только если группе нужен эффект улучшенного ожога."},{["spellID"]=42891,["name"]="Pyroblast",["icon"]="Interface\\Icons\\Spell_Fire_Fireball02",["condition"]="Instant cast with Hot Streak.",["conditionRu"]="Мгновенно при проке «Путь огня»."},{["spellID"]=47610,["name"]="Frostfire Bolt",["icon"]="Interface\\Icons\\Ability_Mage_FrostFireBolt",["condition"]="Filler between refreshes and procs.",["conditionRu"]="Заполнитель между обновлениями и проками.",["ffbIcon"]="Interface\\Icons\\Ability_Mage_FrostFireBolt"}}}}},["DEATHKNIGHT:Blood dps"]={["classToken"]="DEATHKNIGHT",["sourceSpec"]="Blood dps",["role"]="melee",["pve"]={["overview"]={["ruRU"]={"Кровь — вариант рыцаря смерти для урона в ближнем бою. Здесь готовый DPS-пресет WoWSims, не танковый билд.","Удар в сердце, удар смерти и отдельное окно урона с танцующим руническим оружием.","Требует контроля болезней, рун и силы рун. Пресет не доказывает превосходство над другими специализациями; стартовые задания DK влияют на доступные очки."},["enUS"]={"Blood melee DPS using the published WoWSims preset, not a tank build.","Heart Strike, Death Strike and a Dancing Rune Weapon damage window.","Requires disease, rune and runic-power management. This preset does not establish superiority over other specs; DK starting quests affect available points."}},["rotation"]={["ruRU"]="Поддерживайте обе болезни. Обновляйте их мором с соответствующим символом; используйте удар смерти и удар в сердце, не теряйте силу рун у предела. Согласуйте истерию, вурдалака и танцующее руническое оружие с усилениями. Лик смерти — расход силы рун, когда основные руны восстанавливаются. Точные условия и особенности комплекта смотрите в APL источника.",["enUS"]="Maintain both diseases and refresh with glyphed Pestilence. Use Death Strike and Heart Strike while avoiding runic-power waste. Coordinate Hysteria, Raise Dead and Dancing Rune Weapon with buffs; use Death Coil during rune downtime. See the source APL for precise conditions and set-specific behavior."},["sources"]={{["url"]="https://github.com/wowsims/wotlk/blob/563e4a08cb15729f1fdcbcf68e6d68224553bfef/ui/deathknight/presets.ts",["sha256"]="45c45e5f834afb24f954ad27ee9b6398f620287cb7fe9e50913c933032ebe458",["date"]="2026-10-19"},{["url"]="https://github.com/wowsims/wotlk/blob/563e4a08cb15729f1fdcbcf68e6d68224553bfef/ui/deathknight/apls/blood_dps.apl.json",["date"]="2026-10-19"}},["builds"]={{["key"]="pve_blood_dps",["title"]="Blood DPS",["titleRu"]="Кровь - урон",["targetLevel"]=80,["talentsString"]="2305120530003303231023001351--2302003050032",["points"]=71,["allocations"]={{["talentID"]=1939,["rank"]=2,["spellID"]=49483,["tree"]=1,["minLevel"]=10,["maxRank"]=2,["name"]="Butchery",["nameRu"]="Butchery"},{["talentID"]=1945,["rank"]=3,["spellID"]=49491,["tree"]=1,["minLevel"]=10,["maxRank"]=3,["name"]="Subversion",["nameRu"]="Subversion"},{["talentID"]=1938,["rank"]=5,["spellID"]=49393,["tree"]=1,["minLevel"]=15,["maxRank"]=5,["name"]="Bladed Armor",["nameRu"]="Bladed Armor"},{["talentID"]=1948,["rank"]=1,["spellID"]=49004,["tree"]=1,["minLevel"]=15,["maxRank"]=3,["name"]="Scent of Blood",["nameRu"]="Scent of Blood"},{["talentID"]=2217,["rank"]=2,["spellID"]=55108,["tree"]=1,["minLevel"]=15,["maxRank"]=2,["name"]="Two-Handed Weapon Specialization",["nameRu"]="Two-Handed Weapon Specialization"},{["talentID"]=1943,["rank"]=5,["spellID"]=49480,["tree"]=1,["minLevel"]=2